insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:reading-writing-information-ideas')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'reading-writing-information-ideas', 'reading-writing-information-ideas', 'Reading and Writing: Information and Ideas', 'Central ideas, textual and quantitative evidence, and inferences on the digital SAT: what each question asks, a repeatable method, original worked examples, traps, timing and a drill with explanations.', 'published', 'public', 'en', 3, 'Reading and Writing: Information and Ideas | SAT Playbook', 'Master SAT Information and Ideas questions: central ideas and details, command of evidence with texts, tables and graphs, and inferences, with original examples and drills.', array['SAT', 'digital SAT', 'Reading and Writing', 'Information and Ideas', 'command of evidence', 'inferences', 'central ideas', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"reading-writing-information-ideas","module_group":"domain_reading_writing","migration_group":"reading_writing","hero_kicker":"Module 3","word_count":4982,"section_count":29,"reading_minutes":25,"estimated_reading_minutes":25,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Practice evidence and inference questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=command_of_evidence"},{"label":"Hard evidence questions only","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=command_of_evidence&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
