insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:reading-writing-information-ideas:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why Information and Ideas matters', '{"markdown":"Information and Ideas checks whether you can use a short text accurately: find its main point, locate a detail, choose evidence that proves a claim, read a table or graph against a sentence, and draw a conclusion the text supports.\n\nCollege Board''s specifications put this domain at **about 26% of the section, roughly 12 to 14 of the scored questions**. That is close to one question in four. Because the skills are the same in both modules, a student who builds a reliable method here improves in Module 1 and in whichever second module they are routed to.\n\nThis domain rewards discipline more than talent: almost every wrong answer goes beyond the text, answers a different question, is true but irrelevant, or misreads the data. Learn to name those reasons and elimination becomes fast."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What you will be able to do', '{"items":["Recognise the three Information and Ideas skills from the question stem alone.","State the main idea of a 25 to 150 word passage in your own words before reading the choices.","Choose a finding or quotation that directly supports or weakens a stated claim.","Read a table, bar graph or line graph against a sentence and pick the data that completes it accurately.","Complete an inference with the choice the text forces, not the one that merely sounds plausible.","Eliminate distractors by naming exactly why each one fails.","Pace this block of questions so it does not steal time from Expression of Ideas at the end of the module."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where these questions sit in a module', '{"markdown":"Each Reading and Writing module has 27 questions in 32 minutes. Two of them are unscored pretest questions that look like all the others, so treat every question as if it counts. Each passage is 25 to 150 words long and has exactly one question.\n\nQuestions appear in domain blocks, always in this order:\n\n1. **Craft and Structure** (words in context, text structure and purpose, cross-text connections)\n2. **Information and Ideas** (central ideas, evidence, inferences)\n3. **Standard English Conventions** (boundaries; form, structure and sense)\n4. **Expression of Ideas** (transitions, rhetorical synthesis)\n\nInside the Information and Ideas block, questions on the same skill are grouped and run from easier to harder. You will usually see main idea and detail questions, then evidence questions, then inference completions. Each new skill group starts easier again, so one hard inference says nothing about what follows."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'The three skills at a glance', '{"markdown":"| Skill | What the question gives you | What it asks you to do |\n|---|---|---|\n| Central Ideas and Details | A short prose passage or poem excerpt | Identify the main idea, or a specific detail the text states |\n| Command of Evidence: Textual | A claim, hypothesis or interpretation in the passage | Pick the finding or quotation that best supports, illustrates or weakens it |\n| Command of Evidence: Quantitative | A passage plus a table, bar graph or line graph | Pick the data that accurately completes or supports a statement |\n| Inferences | A passage that ends with a blank | Choose the conclusion that most logically follows from the text |\n\n**All four** are multiple-choice questions with four options and one best answer."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'How the questions are phrased', '{"markdown":"The stem tells you the skill in two seconds, so read it before the passage.\n\n- **Main idea:** which choice best states the main idea, or best describes what happens.\n- **Detail:** \"according to the text\" or \"based on the text\", followed by why, how or what.\n- **Textual evidence:** which finding, if true, would most directly support or weaken a claim, or which quotation best illustrates a claim about a work.\n- **Quantitative evidence:** which choice uses data from the table or graph to complete or support a statement.\n- **Inference:** which choice most logically completes the text, which ends with a blank."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Central Ideas and Details: what is tested', '{"markdown":"**Main idea questions** test whether you can see the whole passage at once. The correct answer covers the full text at the right level: not one supporting detail, not a broader claim than the author makes.\n\n**Detail questions** are narrower: find the sentence that answers a specific question and recognise its paraphrase among the choices.\n\nPassages come from science, history and social studies, the humanities and literature. Literature can be prose fiction, drama or poetry, often from older public-domain works with formal language. The task stays the same: what is happening, and what does the text say?"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'A method for central idea questions', '{"markdown":"1. **Read the stem** and confirm it asks for the main idea or a detail.\n2. **Read the whole passage once** without rereading lines.\n3. **Summarise in about ten words:** who or what, and what is said about it.\n4. **Check the last sentence.** Short passages often build to a conclusion, a contrast (\"however\", \"yet\") or a researcher''s interpretation, and the main idea usually includes it.\n5. **Eliminate by scope:** choices covering one sentence, going beyond the author, or about something mentioned in passing.\n6. **Pick the survivor that matches your summary.**\n\nFor detail questions, replace step 3 with: find the sentence that answers the stem, then match its paraphrase."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Worked example 1: central idea (science)', '{"markdown":"*All passages in this module are original and written by Schood for practice. Researchers named in them are fictional.*\n\n> Honeybee colonies regulate the temperature of their hives with surprising precision. When the brood area cools, worker bees cluster over the cells and shiver their flight muscles without moving their wings, producing heat. When the hive overheats, other workers carry droplets of water inside and fan their wings to speed evaporation. Ecologist Mara Ilves notes that no single bee monitors the whole hive; each worker responds only to the temperature it senses nearby, yet the combined result is a stable environment for the developing larvae.\n\n**Question:** Which choice best states the main idea of the text?\n\n- A) Honeybees use their flight muscles mainly to warm the hive rather than to fly.\n- B) A honeybee colony keeps its brood area stable because many workers each react to local conditions.\n- C) Water is the most important resource a honeybee colony needs in hot weather.\n- D) Researchers have not yet determined how honeybees detect changes in temperature.\n\n**Answer: B.** A ten-word summary might be \"bees keep hive temperature stable without anyone controlling the whole\". B captures both the outcome (stable conditions) and the mechanism Ilves emphasises (individual workers reacting to what they sense nearby).\n\n- **A** distorts a detail. Shivering is one heating method, but the text never compares heating to flying, and \"mainly\" is unsupported.\n- **C** inflates a detail. Water appears in one sentence about cooling; the text never ranks resources.\n- **D** contradicts the passage, which says each worker responds to the temperature it senses."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Command of Evidence (Textual): what is tested', '{"markdown":"Textual evidence questions give you a claim and ask which piece of evidence bears on it most directly. There are two common shapes.\n\n- **Finding questions.** A researcher has a hypothesis. Four possible findings are offered, introduced as \"if true\". You choose the one that would most directly support (or, in some questions, weaken) the hypothesis. You are not judging whether the findings are realistic; you are judging logical fit.\n- **Quotation questions.** The passage makes a claim about a literary work, such as a poem or novel. Four quotations from that work are offered, and you choose the one that best illustrates the claim.\n\nThe key word is *directly*. The correct choice connects to the exact relationship in the claim. If the hypothesis is that X causes Y, the best evidence shows Y changing when X changes, ideally compared with a case where X is absent."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'A method for textual evidence questions', '{"markdown":"1. **Find the claim** in the passage and underline its key parts mentally: the subject, the relationship and the outcome.\n2. **Rewrite it as a test.** \"If Reyna is right, I should see ___.\" Fill in the blank before looking at the choices.\n3. **Check each choice against your test.** Does it involve the same subject and the same outcome? Does it show the relationship, not just mention the topic?\n4. **For weaken questions, flip the test.** \"If Reyna is wrong, I should see ___.\"\n5. **For quotation questions, split the claim into parts.** If the claim says the speaker feels both admiration and unease, the right quotation shows both; a quotation showing only admiration is half an answer."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Worked example 2: textual evidence (social science)', '{"markdown":"> In several cities, planners have replaced some on-street parking spaces with small public seating areas called parklets. Economist Tomas Reyna hypothesises that parklets increase spending at nearby small businesses, because people who stop to sit are more likely to enter shops they would otherwise walk past.\n\n**Question:** Which finding, if true, would most directly support Reyna''s hypothesis?\n\n- A) Parklets cost less to build than most other forms of public seating.\n- B) Shops beside newly installed parklets recorded higher sales than comparable shops on the same streets without parklets.\n- C) Many residents say parklets make their neighbourhoods more attractive.\n- D) Cities that installed parklets also added new bicycle lanes during the same period.\n\n**Answer: B.** The test is \"if Reyna is right, spending near parklets should rise\". B shows exactly that, and the comparison with similar shops on the same streets rules out a simple explanation such as a busier street.\n\n- **A** is about cost, not spending at businesses.\n- **C** is about attractiveness. Residents liking parklets does not show anyone spends more money.\n- **D** introduces a second change that would make any sales increase harder to attribute to parklets. It is irrelevant at best and weakening at worst."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Command of Evidence (Quantitative): reading tables and graphs', '{"markdown":"These questions pair a passage with a table, bar graph or line graph. The passage makes a statement, and you choose the choice that uses the data accurately **and** supports that statement. So every wrong choice fails in one of two ways:\n\n- **It misreads the data:** wrong row, column, unit or year, or a reversed comparison.\n- **It reads the data correctly but does not support the statement.**\n\nThe second trap is more dangerous, because checking the number makes you feel confident. Accuracy is necessary but not enough. Before you start, spend five seconds on the title, labels, units and legend."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'A method for quantitative evidence questions', '{"markdown":"1. **Read the stem, then the last sentence of the passage.** That sentence holds the claim the data must support.\n2. **Label the claim''s parts.** Which groups are compared? Which variable? Is it a difference, a trend, a highest value or a combination?\n3. **Read the graphic''s labels and units.**\n4. **Predict the data you need.** \"I need Ridgeback''s number in low rainfall, compared with the other two varieties.\"\n5. **Check accuracy, then relevance.** For each choice, first verify the numbers against the graphic, then ask whether that fact proves the claim. Eliminate on either failure.\n6. **Watch for two-part claims.** If the claim has a \"though\" or \"but\", the right choice usually covers both parts."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Worked example 3: quantitative evidence (table)', '{"markdown":"> A student studying school gardens compared the harvests of three bean varieties grown in identical plots. She concluded that the variety called Ridgeback is the best choice for gardens that receive little rain, even though it is not the most productive variety under normal rainfall.\n\n**Average harvest per plot (kilograms)**\n\n| Variety | Normal rainfall | Low rainfall |\n|---|---|---|\n| Ridgeback | 4.1 | 3.6 |\n| Sunpole | 5.3 | 2.2 |\n| Marrow Gold | 4.6 | 2.9 |\n\n**Question:** Which choice best describes data from the table that support the student''s conclusion?\n\n- A) Sunpole produced 5.3 kilograms per plot under normal rainfall, more than either other variety.\n- B) Under low rainfall, Ridgeback produced 3.6 kilograms per plot, more than either other variety, while under normal rainfall it produced less than both of them.\n- C) Every variety produced less under low rainfall than under normal rainfall.\n- D) Marrow Gold produced 4.6 kilograms per plot under normal rainfall and 2.9 kilograms under low rainfall.\n\n**Answer: B.** The conclusion has two parts: Ridgeback is best in low rainfall, and it is not the most productive in normal rainfall. B covers both, and the numbers are right (3.6 is greater than 2.9 and 2.2; 4.1 is less than 4.6 and 5.3).\n\n- **A** is accurate and relates to the second half, but says nothing about Ridgeback in low rainfall, the main point.\n- **C** is accurate but true of all three varieties, so it cannot single out Ridgeback.\n- **D** is accurate but about the wrong variety.\n\nNotice that all four choices are numerically correct. Only relevance separates them."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Inferences: what is tested', '{"markdown":"**Inference questions** end the passage with a blank and ask which choice most logically completes it. The correct answer is the conclusion the text forces: if every sentence is true, the answer must be true. It is not the most interesting conclusion or the most likely one in real life.\n\nMany inference passages give a general rule, then a specific observation, then a blank that combines them. Others set up an expectation, present data that does not fit, and ask what the mismatch implies. These are often the hardest questions in the block because the wrong choices sound reasonable, so hold them to a strict standard of proof."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'A method for inference questions', '{"markdown":"1. **Read the full passage, then reread the sentence just before the blank.** It usually tells you what kind of conclusion is needed (a cause, a consequence, a limitation, a prediction).\n2. **Write your own completion first**, in plain words. Keep it modest.\n3. **Test each choice with \"must this be true?\"** If you can imagine the passage being entirely true while the choice is false, eliminate it.\n4. **Beware of strong language.** Words like *always*, *only*, *proves*, *all* and *never* demand more support than a short passage usually gives. They are not automatically wrong, but they must be justified.\n5. **Beware of true-but-unsupported facts.** A choice can be correct in the real world and still be wrong on the SAT if the passage does not establish it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked example 4: inference (history)', '{"markdown":"> In the 1850s, most long-distance mail between the eastern United States and California travelled by ship or by overland stagecoach routes that took weeks. The Pony Express, a horseback relay service that began in 1860, cut delivery to roughly ten days. When telegraph lines linked the East and West Coasts in October 1861, messages could cross the continent almost instantly, and the Pony Express shut down within days. This timing suggests that \\_\\_\\_\\_\\_\\_\n\n- A) the Pony Express''s main value to customers had been its speed, an advantage the telegraph overtook.\n- B) the Pony Express had lost money from the day it began operating.\n- C) customers preferred ships to horseback riders for sending letters.\n- D) the telegraph line was built mainly in order to replace the Pony Express.\n\n**Answer: A.** The passage stresses speed: weeks by ship or stage, about ten days by Pony Express, almost instantly by telegraph. Its closure \"within days\" of the telegraph link is most logically explained by the loss of its speed advantage.\n\n- **B** may be historically accurate, but the passage says nothing about finances. This is the classic true-but-unsupported trap.\n- **C** has no support; the passage implies the opposite for speed-sensitive messages.\n- **D** reverses the logic. The timing tells us about the Pony Express''s dependence on speed, not about the builders'' motives."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Worked example 5: literary narrative', '{"markdown":"> *Original passage.* Ines had rehearsed the speech for a week, pacing her bedroom until the floorboards seemed to know it by heart. Yet when the hall fell quiet and every face turned toward her, the opening sentence she had polished so carefully simply would not come. She looked down at her notes, then at her grandfather in the third row, who gave a small, unhurried nod, as if they had all the time in the world. Ines set the notes aside and began, in her own plain words, to tell them about the river.\n\n**Question:** Which choice best describes what happens in the text?\n\n- A) A speaker forgets her prepared opening but, reassured by a familiar face, begins speaking without her script.\n- B) A speaker refuses to give her speech after noticing her grandfather in the audience.\n- C) A speaker reads her notes word for word because she is afraid of making a mistake.\n- D) A speaker''s grandfather interrupts the event to remind her of the speech.\n\n**Answer: A.** Track the sequence: preparation, a freeze, a glance at her grandfather, his calm nod, then she speaks in her own words. A follows that sequence exactly.\n\n- **B** contradicts the ending; she does speak.\n- **C** contradicts \"set the notes aside\".\n- **D** overstates the grandfather''s role. He nods; he does not interrupt or speak.\n\nLiterature questions reward close attention to sequence and to small actions. The nod and the set-aside notes carry the meaning."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'The traps that cost the most points', '{"markdown":"- **Too narrow:** a main idea choice that restates one detail.\n- **Too broad:** a claim bigger than the passage (\"scientists now agree...\").\n- **Recycled language:** striking words from the passage, connected wrongly.\n- **True but irrelevant:** correct data that does not bear on the claim.\n- **True but unsupported:** correct in real life, not established by the text.\n- **Half an answer:** supports one part of a two-part claim.\n- **Reversed relationship:** cause and effect swapped, or more turned into less.\n- **Extreme wording** the passage does not justify."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'callout', 'The prove-it rule', '{"label":"The prove-it rule","body":"Before you commit to an answer, point to the words in the passage, or the numbers in the graphic, that prove it. If you cannot point to them, you are guessing about the world rather than reading the text. On Information and Ideas questions the text is the only authority, and the correct answer always has visible support."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Decision rules for Information and Ideas', '{"markdown":"- **Stem first, always.**\n- **Predict before reading the choices** for main idea, evidence and inference questions.\n- **Eliminate only for a named reason:** \"too narrow\", \"irrelevant\", \"unsupported\".\n- **For data questions, check accuracy, then relevance.** Both must pass.\n- **For two-part claims, require both parts.**\n- **Between two survivors, prefer the more modest one** unless the text clearly supports the stronger claim.\n- **Never leave a blank.** There is no penalty for wrong answers, and College Board advises guessing over leaving a question unanswered."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Timing guidance', '{"markdown":"A Reading and Writing module gives you 32 minutes for 27 questions, about 71 seconds per question on average. Evidence and inference questions usually take longer than average, so plan with ranges.\n\n| Question type | Typical target | Mark and move if past |\n|---|---|---|\n| Main idea or detail | 45 to 60 seconds | 90 seconds |\n| Textual evidence (finding) | 60 to 75 seconds | 100 seconds |\n| Quantitative evidence | 60 to 90 seconds | 110 seconds |\n| Inference completion | 60 to 90 seconds | 120 seconds |\n\nAt the \"mark and move\" point, choose your best remaining answer, use **Mark for Review** and continue. Spending four minutes on one hard inference usually costs you quicker points in Expression of Ideas at the end of the module. Return to marked questions only after you have seen every question.\n\nA useful checkpoint: aim to reach the start of the Standard English Conventions block with at least 14 to 16 minutes remaining. Adjust this to your own pace after a full practice test."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Drill: questions', '{"markdown":"*Six original practice items. Answer all of them before reading the explanations in the next section.*\n\n**1.** For centuries, builders of Gothic cathedrals faced a problem: tall stone walls pierced by large windows tended to push outward and could collapse. The flying buttress, an arch that braces a wall from outside the building, solved this by carrying the outward thrust down to the ground away from the wall. Because the walls no longer had to resist all of that force themselves, architects could make them thinner and fill them with the expanses of stained glass for which cathedrals such as Chartres are known.\n\nWhich choice best states the main idea of the text?\n- A) The flying buttress allowed large windows by moving structural force away from the walls.\n- B) Stained glass was invented to decorate the walls of Gothic cathedrals.\n- C) Chartres was the first cathedral to use flying buttresses.\n- D) Gothic builders preferred thin walls because stone was scarce.\n\n**2.** Linguist Aiko Brandt claims that children raised in bilingual households begin combining words into two-word phrases later than children in monolingual households, because they must sort vocabulary from two languages.\n\nWhich finding, if true, would most directly weaken Brandt''s claim?\n- A) Bilingual children often mix words from both languages in a single phrase.\n- B) In a large study, bilingual and monolingual children began producing two-word phrases at about the same average age.\n- C) Monolingual children vary widely in the age at which they say their first word.\n- D) Parents in bilingual households often use each language in different settings.\n\n**3.** A city tracked how commuters travelled to work before and after it opened a light-rail line in 2022.\n\n**Share of commuters by mode (percent)**\n\n| Mode | 2021 | 2023 |\n|---|---|---|\n| Car | 61 | 52 |\n| Bus | 18 | 15 |\n| Light rail | 0 | 14 |\n| Bicycle or walking | 21 | 19 |\n\nSome council members worried that the light-rail line would mainly draw riders away from buses rather than from cars. The data suggest otherwise: from 2021 to 2023, \\_\\_\\_\\_\\_\\_\n\nWhich choice most effectively uses data from the table to complete the statement?\n- A) the share of commuters who rode buses fell from 18 percent to 15 percent.\n- B) the share of commuters who drove fell by 9 percentage points, while the share who rode buses fell by only 3.\n- C) the share who cycled or walked was larger than the share who rode buses in both years.\n- D) light rail carried 14 percent of commuters in 2023.\n\n**4.** A lichen is a partnership between a fungus and an alga. Because lichens absorb water and nutrients directly from the air rather than from soil, they also absorb airborne pollutants, and many species die when levels of sulfur dioxide rise. Surveying a city''s parks, botanists found many lichen species in parks at the city''s edge but only one or two hardy species in parks near its industrial centre. The survey therefore suggests that \\_\\_\\_\\_\\_\\_\n\nWhich choice most logically completes the text?\n- A) the air near the industrial centre likely contains more sulfur dioxide or similar pollutants than the air at the city''s edge.\n- B) the soil in the central parks lacks nutrients that lichens need.\n- C) hardy lichen species grow faster than other lichen species.\n- D) the fungus in a lichen can survive without its algal partner.\n\n**5.** A museum offered free admission on the first Sunday of every month for a year, hoping to attract people who had never visited. Attendance on those Sundays roughly doubled compared with other Sundays. A follow-up survey, however, found that most free-Sunday visitors had visited the museum at least once in the previous year, paying regular admission, and had simply moved their visits to the free days. These findings suggest that \\_\\_\\_\\_\\_\\_\n\nWhich choice most logically completes the text?\n- A) the free Sundays were less successful at meeting the museum''s goal than the attendance figures alone imply.\n- B) the museum should raise its regular admission price.\n- C) the museum should end all free-admission programmes immediately.\n- D) most people who visit museums prefer Sundays to other days.\n\n**6.** Researchers recorded the average nightly sleep of three groups of students during exam week and the groups'' average scores on a memory test.\n\n| Group | Average sleep (hours) | Average memory score (out of 50) |\n|---|---|---|\n| A | 5.5 | 31 |\n| B | 7.0 | 38 |\n| C | 8.5 | 39 |\n\nThe researchers concluded that more sleep was associated with higher memory scores but that the benefit appeared to level off beyond about seven hours.\n\nWhich choice best describes data from the table that support the researchers'' conclusion?\n- A) Group C slept the most and had the highest average memory score.\n- B) Group B scored 7 points higher than Group A, while Group C scored only 1 point higher than Group B.\n- C) Group A slept 5.5 hours on average and scored 31.\n- D) All three groups slept fewer than 9 hours per night on average."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: answers and explanations', '{"markdown":"**1. A (central idea).** The passage moves from a problem (walls pushed outward) to a solution (buttresses carry the thrust away) to a result (thinner walls, large windows). A covers all three. B invents a claim about the origin of stained glass. C is not stated; Chartres is only an example. D gives a reason (scarce stone) the text never mentions.\n\n**2. B (textual evidence, weaken).** The claim is that bilingual children start two-word phrases later. If that is wrong, the ages should be about the same, which is what B reports. A concerns how phrases are built, not when they start. C is about first words in monolingual children only, with no comparison. D describes parents'' habits and does not address timing.\n\n**3. B (quantitative).** The worry is that light rail would draw mainly from buses. Car use fell by 9 points (61 to 52) and bus use by 3 (18 to 15), so the larger drop was among drivers, which contradicts the worry. A is accurate but on its own appears to support the worry. C is accurate (21 and 19 versus 18 and 15) but irrelevant to where rail riders came from. D is accurate but does not show where those riders came from.\n\n**4. A (inference).** The passage sets a rule (many lichens die when sulfur dioxide rises) and an observation (few species near the industrial centre). Together they suggest more pollution there. The word \"likely\" keeps the claim appropriately modest. B contradicts the passage: lichens do not depend on soil. C and D introduce ideas the passage never discusses.\n\n**5. A (inference).** The goal was new visitors; the survey shows most free-day visitors were not new. So attendance doubling overstates success against that goal. B and C are recommendations the passage does not support, and C''s \"all\" and \"immediately\" are far too strong. D is not supported; the passage compares free Sundays with other Sundays, not Sundays with other days.\n\n**6. B (quantitative).** The conclusion has two parts: more sleep goes with higher scores, and the gain levels off after about seven hours. B shows a large gain from A to B (31 to 38, 7 points) and a small one from B to C (38 to 39, 1 point). A supports only the first part. C reports one group without comparison. D is accurate but irrelevant.\n\nIf you missed an item, write down which trap caught you; the traps that repeat are the habits to fix first."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'A weekly practice routine', '{"markdown":"About 25 to 35 minutes a day, alongside the rest of your SAT preparation:\n\n- **Day 1: main idea and detail.** Ten untimed questions with the full method, then review every miss: redo it cold, point to the proof, name the flaw in your choice and log the trap.\n- **Day 2: textual evidence.** Ten questions; write an \"if right, I should see\" prediction before each.\n- **Day 3: quantitative evidence.** Eight to ten questions; say the accuracy check and the relevance check for each choice.\n- **Day 4: inferences.** Eight to ten completions; write your own completion first.\n- **Day 5: mixed and timed.** Fifteen questions at about 75 seconds each, with mark and move.\n- **Day 6: error log.** Redo this week''s misses and count which trap appears most.\n- **Day 7: rest, or a full-length Bluebook practice test** if your plan schedules one.\n\nShift the mix toward the skill your practice results show as weakest."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Priorities by current section score', '{"markdown":"These are priorities by your current Reading and Writing section score, not promises of points; improvement depends on your starting point, time and review quality.\n\n**Below about 500**\n- Read the stem first and summarise every passage in ten words.\n- Focus on main idea and detail questions, which reward the method most directly.\n- Read graphic titles, labels and units before anything else.\n\n**About 500 to 650**\n- Check accuracy and relevance separately on every evidence question.\n- Predict before reading the choices on every inference.\n- Use an error log; \"true but irrelevant\" and \"half an answer\" are the usual leaks.\n\n**Above about 650**\n- Target the hardest inference and quotation questions, where choices differ by a word.\n- Practise with older literary texts and dense science passages.\n- Apply the prove-it rule even when you feel sure, and review the correct answers you hesitated on."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Frequently asked questions', '{"markdown":"### Do I need outside knowledge for science or history passages?\nNo. Everything you need is in the passage. Outside knowledge can hurt if it pulls you toward a choice that is true in the world but not supported by the text, as in worked example 4.\n\n### Are the questions in the second module different?\nThe skills are the same. In the higher-difficulty second module, expect denser passages, more abstract claims and closer distractors. The method does not change.\n\n### What if two choices both seem supported?\nReread the claim or the sentence before the blank and ask which choice addresses it more directly. One of the two is usually slightly too broad or covers only half of the claim.\n\n### How do I handle a graph with confusing labels?\nRead the title, then each heading and the units. Say what one cell means (\"in 2023, 14 percent of commuters used light rail\"). Once one cell makes sense, the rest will."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Related practice', '{"markdown":"- [Information and Ideas questions in the SAT Practice bank](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=command_of_evidence)\n- [Hard evidence and inference questions](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=command_of_evidence&difficulty=hard)\n- [Today''s personalised practice session](https://practice.sat.schood.online/today)\n- [Take a full timed test in the SAT Simulator](https://sat.schood.online)\n\nOfficial free practice is also available as full-length adaptive tests in the Bluebook app and through Official Digital SAT Prep on Khan Academy."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (29, 'rich_text', 'Next steps', '{"markdown":"- Continue with [Craft and Structure](https://playbook.sat.schood.online/reading-writing-craft-structure), the block that comes before this one in every module.\n- Then study [Expression of Ideas](https://playbook.sat.schood.online/reading-writing-expression-of-ideas) and [Standard English Conventions](https://playbook.sat.schood.online/reading-writing-conventions).\n- Learn how module 1 performance affects module 2 in [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules).\n- Set a realistic target with [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n- New to the test? Start with [SAT Essentials](https://playbook.sat.schood.online/sat-essentials)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:reading-writing-information-ideas')::uuid
on conflict do nothing;

