-- Module 4: reading-writing-craft-structure (28 sections, 4391 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:reading-writing-craft-structure')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'reading-writing-craft-structure', 'reading-writing-craft-structure', 'Reading and Writing: Craft and Structure', 'Words in context, text structure and purpose, and cross-text connections on the digital SAT: how each question works, a method you can repeat, original worked examples, traps, timing and a drill with explanations.', 'published', 'public', 'en', 4, 'Reading and Writing: Craft and Structure | SAT Playbook', 'Master SAT Craft and Structure questions: words in context, text structure and purpose, and cross-text connections, with original examples, traps, timing and drills.', array['SAT', 'digital SAT', 'Reading and Writing', 'Craft and Structure', 'words in context', 'text structure', 'cross-text connections', 'SAT Playbook']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"reading-writing-craft-structure","module_group":"domain_reading_writing","migration_group":"reading_writing","hero_kicker":"Module 4","word_count":4391,"section_count":28,"reading_minutes":22,"estimated_reading_minutes":22,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Practice words-in-context questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=vocabulary_in_context"},{"label":"Hard Craft and Structure questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=vocabulary_in_context&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:reading-writing-craft-structure:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why Craft and Structure matters', '{"markdown":"Craft and Structure asks how a text works, not just what it says. You choose the most precise word for a context, describe how a passage is built or why a sentence is there, and compare how two authors would respond to each other.\n\nIt is the largest Reading and Writing domain: College Board''s specifications put it at **about 28% of the section, roughly 13 to 15 scored questions**. It also comes first in every module, so a confident start here sets your pace and your mood for the rest of the section.\n\nThese questions reward two things you can train: a working vocabulary of academic words and their less common meanings, and the habit of describing a passage''s moves in plain language before looking at the choices."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'What you will be able to do', '{"items":["Recognise the three Craft and Structure skills from the question stem.","Predict a word for a blank from the context before reading the choices.","Spot when a familiar word is being used in a less common sense.","Describe the overall structure of a passage as a sequence of moves.","State the function of a single sentence in relation to the sentences around it.","Identify the main purpose of a short text.","Compare two texts and predict how one author would respond to the other.","Move quickly through vocabulary questions so you bank time for the rest of the module."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where these questions sit in a module', '{"markdown":"Each Reading and Writing module has 27 questions in 32 minutes, two of which are unscored pretest questions you cannot identify. Each passage is 25 to 150 words and has one question.\n\nThe domains always appear in the same order:\n\n1. **Craft and Structure** (this module)\n2. **Information and Ideas**\n3. **Standard English Conventions**\n4. **Expression of Ideas**\n\nWithin Craft and Structure, questions on the same skill are grouped and arranged from easier to harder. You will typically meet a run of words-in-context questions first, then text structure and purpose, then cross-text connections. Because each group restarts at an easier level, the first structure question after a hard vocabulary question is often manageable."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'The three skills at a glance', '{"markdown":"| Skill | What you see | What you do |\n|---|---|---|\n| Words in Context | A passage with a blank, or a word in a sentence | Choose the most logical and precise word, or the meaning of a word as used |\n| Text Structure and Purpose | A passage, sometimes with one sentence marked | Describe the overall structure, the main purpose, or the function of a part |\n| Cross-Text Connections | Two short texts on the same topic | Describe how one author would respond to, or relate to, the other |\n\n**All three** use four-option multiple-choice questions with one best answer."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'How the questions are phrased', '{"markdown":"- **Words in context, blank:** which choice completes the text with the most logical and precise word or phrase.\n- **Words in context, meaning:** as used in the text, what a given word most nearly means.\n- **Overall structure:** which choice best describes the overall structure of the text.\n- **Main purpose:** which choice best states the main purpose of the text.\n- **Function:** which choice best describes the function of a marked sentence or portion in the text as a whole. On the test the sentence is underlined; in this module it is shown in **bold**.\n- **Cross-text:** based on the texts, how the author of Text 2 would most likely respond to a claim or view in Text 1, or what both authors would agree on."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Words in Context: what is tested', '{"markdown":"Words-in-context questions test precision. All four choices are real words, and several may be loosely related to the topic. Only one fits both the meaning of the sentence and the logic of the surrounding text.\n\nTwo kinds of difficulty appear:\n\n- **Logic.** The blank sits inside a contrast (\"although\", \"yet\"), a cause (\"because\", \"so\") or an explanation after a colon. The right word must fit that relationship.\n- **Vocabulary level.** Harder questions use precise academic words (such as *tenuous*, *corroborate*, *ambivalent*) or familiar words in less common senses (*entertain* meaning consider, *qualified* meaning limited).\n\nYou do not need to know every word in the choices. If you can predict the meaning needed and know three of the four choices, you can often reach the answer by elimination."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'A method for words-in-context questions', '{"markdown":"1. **Cover the choices** (mentally, or by not looking yet).\n2. **Find the clue.** Look for a definition after a colon, a contrast word, a cause-and-effect link or a restatement elsewhere in the passage.\n3. **Predict your own word**, even a simple one like \"good\", \"small\" or \"doubtful\". Note whether it is positive, negative or neutral.\n4. **Compare each choice to your prediction**, not to the passage''s topic.\n5. **Plug the survivor back in** and read the whole sentence. It should sound precise, not merely acceptable.\n6. **For \"most nearly means\" questions**, replace the word with each choice and check which keeps the sentence''s meaning. Expect the common meaning of the word to be a trap."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Worked example 1: words in context (science)', '{"markdown":"*All passages in this module are original and written by Schood for practice. People named in them are fictional.*\n\n> Coral reefs cover less than one percent of the ocean floor, yet they \\_\\_\\_\\_\\_\\_ an extraordinary share of marine life: by some estimates, about a quarter of all ocean species depend on reefs at some stage of their lives.\n\n**Question:** Which choice completes the text with the most logical and precise word?\n\n- A) support\n- B) depict\n- C) exceed\n- D) reject\n\n**Answer: A.** The clue is the explanation after the colon: many species depend on reefs. The prediction is something like \"provide for\". *Support* fits exactly.\n\n- **B** means to show in a picture or description, which reefs do not do.\n- **C** is a comparison word that creates nonsense: reefs cannot \"exceed\" a share of marine life.\n- **D** is the opposite of the meaning the colon requires.\n\nThe contrast word *yet* also helps: small area, *yet* a large role."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Worked example 2: a familiar word in an unfamiliar sense', '{"markdown":"> *Original passage.* The old captain was not a man to be hurried. He would **entertain** a new proposal for days, turning it over in silence, before giving any answer at all.\n\n**Question:** As used in the text, what does the word \"entertain\" most nearly mean?\n\n- A) amuse\n- B) consider\n- C) host\n- D) perform\n\n**Answer: B.** The surrounding words explain the meaning: he turns the proposal over in silence for days before answering. That is considering it.\n\n- **A** is the most common meaning of *entertain*, which is exactly why it is the trap. The captain is not amusing anyone.\n- **C** fits guests, not proposals.\n- **D** fits a performer on stage, not someone weighing an idea.\n\n**Rule:** when a stem asks what a common word \"most nearly means\", the everyday meaning is usually wrong. The test chose that word because it has a second sense."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Building vocabulary that actually pays off', '{"markdown":"Memorising long word lists is slow and forgetful. These habits work better for the SAT:\n\n- **Learn words from your own misses.** Every unknown word in a practice question goes into your notebook with the sentence it appeared in.\n- **Learn second meanings of common words.** Words like *qualify*, *check*, *conceive*, *sound*, *grave*, *novel* and *arrest* have academic senses the test likes.\n- **Group words by charge and strength.** For example, *doubtful*, *skeptical* and *dismissive* are all negative toward an idea, but in increasing strength. Precision questions often turn on that difference.\n- **Read academic prose daily.** Ten minutes of science journalism, history writing or a classic novel exposes you to the vocabulary in its natural context.\n- **Review with spaced repetition.** Revisit new words after one day, three days and a week."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Text Structure and Purpose: what is tested', '{"markdown":"These questions ask you to step back and describe the passage as an author''s plan. Three versions appear:\n\n- **Overall structure:** the sequence of moves, such as \"presents a view, then challenges it\" or \"describes a problem, then a proposed solution, then a limitation\".\n- **Main purpose:** why the author wrote the text, expressed as a verb: to explain, to argue, to describe, to challenge, to illustrate, to compare.\n- **Function of a part:** what one sentence does for the passage, such as introducing a contrast, giving an example, stating a conclusion or correcting an assumption.\n\nThe choices are often written in abstract language. That is deliberate: the test checks whether you can translate the concrete passage into a general description."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'A method for structure and purpose questions', '{"markdown":"1. **Label each sentence with a move** as you read: *claim*, *example*, *contrast*, *evidence*, *conclusion*, *limitation*, *background*.\n2. **For overall structure,** string the labels together: \"background, then contrast, then evidence, then conclusion\".\n3. **For main purpose,** ask why the last sentence exists; short texts usually land their purpose there.\n4. **For function,** read the sentence before and after the marked one. Ask what would be lost if it were deleted.\n5. **Match the abstract choices to your labels.** Check every part of the choice; one wrong word (\"criticises\" when the author only describes) eliminates it.\n6. **Watch the verbs.** *Argue* and *criticise* need a clear opinion in the text; *describe* and *explain* do not."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Worked example 3: overall structure (history)', '{"markdown":"> For decades, historians described medieval European peasants as almost entirely immobile, rarely travelling more than a few miles from the villages where they were born. More recent studies of court records and manor rolls complicate that picture. These documents show peasants moving between villages to marry, to find work after poor harvests and to settle disputes in regional courts. The evidence suggests that, for many ordinary people, mobility was a routine part of medieval life.\n\n**Question:** Which choice best describes the overall structure of the text?\n\n- A) It presents a traditional view, introduces evidence that challenges it and offers a revised conclusion.\n- B) It describes a historical problem and proposes several possible solutions.\n- C) It compares two kinds of historical documents and explains why one is more reliable.\n- D) It summarises a debate between historians and declares that neither side is correct.\n\n**Answer: A.** Labels: traditional view (sentence 1), challenge (sentence 2), evidence (sentence 3), revised conclusion (sentence 4). A matches the sequence exactly.\n\n- **B** misreads the passage; there is no problem and no solutions.\n- **C** treats court records and manor rolls as competitors, but the text uses them together.\n- **D** invents a verdict; the author sides with the newer evidence."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Worked example 4: function of a sentence (science)', '{"markdown":"> Many people assume that a tree''s roots reach deep below its trunk, like an underground mirror image of its branches. **In fact, most of a typical tree''s roots lie in the top half-metre of soil.** These shallow roots spread outward, often far beyond the reach of the branches, where they can absorb water from light rain and draw oxygen from loosely packed earth.\n\n**Question:** Which choice best describes the function of the sentence in bold in the text as a whole?\n\n- A) It corrects a common assumption described in the previous sentence.\n- B) It gives an example that supports the common assumption.\n- C) It raises a question that the rest of the text leaves unanswered.\n- D) It explains why trees need oxygen to survive.\n\n**Answer: A.** The first sentence states what \"many people assume\"; the bold sentence opens with \"In fact\" and contradicts it. That is a correction.\n\n- **B** reverses the relationship.\n- **C** is wrong because the bold sentence is a statement, and the final sentence develops it.\n- **D** describes part of the final sentence, not the bold one, and even that sentence does not explain why trees need oxygen.\n\nSignal phrases such as *in fact*, *however*, *for example* and *as a result* are strong clues to function."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Cross-Text Connections: what is tested', '{"markdown":"**Cross-text questions** give you two short texts on the same topic, labelled Text 1 and Text 2. The question usually asks how the author of Text 2 would respond to a specific claim, finding or approach in Text 1. Less often, it asks what both authors would agree on or how they differ.\n\nThe skill is perspective-taking. You must hold one author''s view in mind and apply it to the other author''s claim. The correct answer is usually measured: Text 2 often qualifies, complicates or adds a caution to Text 1, rather than flatly contradicting it.\n\nThese are often the longest questions in the module, because you read two passages for one point. Budget for that, and do not let one cross-text question steal time from the quicker questions ahead."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'A method for cross-text questions', '{"markdown":"1. **Read the question first** and note exactly which claim in Text 1 is being responded to.\n2. **Summarise Text 1 in one sentence**, focusing on that claim.\n3. **Summarise Text 2''s position on the same issue** in one sentence. Does it agree, disagree, qualify or add a condition?\n4. **Predict the response** in your own words: \"Text 2 would say the evidence for Text 1''s claim is weaker than it looks.\"\n5. **Eliminate extreme responses** unless Text 2 is extreme. Most Text 2 authors are cautious, not hostile.\n6. **Check that the answer responds to the right claim**, not to a different detail in Text 1."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked example 5: cross-text connections (social science)', '{"markdown":"> **Text 1.** Some economists argue that a four-day work week would raise productivity. When employees have an extra day to rest, the argument goes, they return more focused and accomplish in four days what previously took five.\n>\n> **Text 2.** Trials of shorter work weeks have often reported happier employees, but measuring productivity in such trials is difficult. Many participating companies volunteered because their managers already expected success, and workers who know they are being studied may work harder simply because of the attention. Until studies account for these factors, claims about productivity deserve caution.\n\n**Question:** Based on the texts, how would the author of Text 2 most likely respond to the argument in Text 1?\n\n- A) By claiming that employees on shorter work weeks are less happy than other employees.\n- B) By cautioning that the evidence for the productivity claim may be shaped by how the trials were set up.\n- C) By agreeing that rest is the main cause of higher productivity.\n- D) By arguing that a five-day week is more productive than a four-day week.\n\n**Answer: B.** Text 2 does not reject the idea; it questions the evidence (self-selected companies, workers aware of being observed) and urges caution.\n\n- **A** contradicts Text 2, which reports happier employees.\n- **C** overstates agreement; Text 2 never accepts the causal claim.\n- **D** is far stronger than Text 2''s cautious position."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'The traps that cost the most points', '{"markdown":"- **The everyday meaning** of a word with a second sense.\n- **Topic words:** a choice related to the subject but not to the logic of the sentence.\n- **Wrong charge:** a negative word where the context is positive, or the reverse.\n- **Wrong strength:** a word that is too strong (*condemn*) or too weak (*question*) for the context.\n- **One wrong word in a structure choice:** \"argues\" for a descriptive passage, \"rejects\" for a passage that qualifies.\n- **Describing the neighbour:** a function choice that describes the sentence before or after the marked one.\n- **Responding to the wrong claim** in a cross-text question.\n- **Extreme cross-text responses** when Text 2 is merely cautious."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'callout', 'The prediction rule', '{"label":"Predict before you look","body":"On every Craft and Structure question, form your own answer before reading the choices: a rough word for a blank, a list of moves for a structure question, a one-sentence response for a cross-text question. The choices are written to sound reasonable, and a prediction is the only reliable defence against four plausible options."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Decision rules for Craft and Structure', '{"markdown":"- **Clue first, prediction second, choices third.**\n- **If a common word is tested for meaning, distrust its common meaning.**\n- **Check charge and strength** for vocabulary, not just topic.\n- **Every word in a structure or purpose choice must be true.** One false word eliminates it.\n- **In function questions, read one sentence before and one after** the marked portion.\n- **In cross-text questions, prefer the measured response** unless Text 2 clearly takes a strong stand.\n- **If you do not know a choice''s meaning, judge the choices you do know.** If three are clearly wrong, choose the unknown word.\n- **Never leave a blank.** There is no wrong-answer penalty."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Timing guidance', '{"markdown":"With 32 minutes for 27 questions, the average is about 71 seconds per question. Craft and Structure is where you can bank time, because words-in-context questions are usually the quickest in the module.\n\n| Question type | Typical target | Mark and move if past |\n|---|---|---|\n| Words in context | 30 to 45 seconds | 75 seconds |\n| Structure or purpose | 50 to 70 seconds | 100 seconds |\n| Function of a sentence | 45 to 65 seconds | 90 seconds |\n| Cross-text connections | 75 to 100 seconds | 130 seconds |\n\n**If you finish Craft and Structure in about 10 to 12 minutes**, you leave yourself a comfortable margin for the evidence and inference questions that follow. When a vocabulary question stalls because you do not know the words, eliminate what you can, choose, mark it and move on. Lingering rarely produces a meaning you did not already know."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Drill: questions', '{"markdown":"*Seven original items. Answer all of them before reading the explanations.*\n\n**1.** The architect''s early buildings were praised as bold experiments, but her later work was more \\_\\_\\_\\_\\_\\_: she abandoned dramatic angles in favour of quiet, simple forms that blended into their surroundings.\n\nWhich choice completes the text with the most logical and precise word?\n- A) restrained\n- B) chaotic\n- C) extravagant\n- D) temporary\n\n**2.** Although the vaccine trial was small, its early results were \\_\\_\\_\\_\\_\\_ enough that regulators approved a larger study: nearly every participant developed a strong immune response.\n\nWhich choice completes the text with the most logical and precise word?\n- A) promising\n- B) ambiguous\n- C) negligible\n- D) controversial\n\n**3.** The new medication does not cure the disease, but it can **arrest** its progress for several years, giving patients valuable time with fewer symptoms.\n\nAs used in the text, what does the word \"arrest\" most nearly mean?\n- A) detain\n- B) halt\n- C) capture\n- D) attract\n\n**4.** Most world maps place north at the top, but this habit is a convention, not a fact of nature. Many medieval European maps placed east at the top, and some early maps made by Islamic geographers placed south at the top. Putting north first became standard only over later centuries, for reasons historians still discuss.\n\nWhich choice best states the main purpose of the text?\n- A) To show that the orientation of world maps is a convention that has varied over time\n- B) To argue that maps should place south at the top\n- C) To explain how navigational instruments were invented\n- D) To criticise medieval mapmakers for their inaccuracy\n\n**5.** *Original passage.* Marguerite''s letters from the city were always cheerful. She described concerts, new friends and the shop windows on the boulevard. **Yet she never once mentioned the job that had taken her there.** Her mother, reading each letter twice at the kitchen table, began to notice what was missing.\n\nWhich choice best describes the function of the sentence in bold in the text as a whole?\n- A) It introduces a detail that complicates the cheerful impression created by the letters.\n- B) It explains why Marguerite moved to the city.\n- C) It shows that Marguerite''s mother disliked the city.\n- D) It summarises the events described in the letters.\n\n**6.** The axolotl, a salamander native to lakes near Mexico City, can regrow lost limbs and even parts of its heart and spinal cord. Researchers have long hoped to learn how. A team led by biologist Iris Navarro identified a group of cells that gather at an injury and appear to signal the surrounding tissue to rebuild. The team cautions, however, that similar cells exist in mammals without producing the same effect.\n\nWhich choice best describes the overall structure of the text?\n- A) It describes a remarkable ability, reports a finding about how it may work and notes a limitation of that finding.\n- B) It explains why axolotls are rare and proposes a way to protect them.\n- C) It compares axolotls with mammals and concludes that mammals regenerate better.\n- D) It presents two competing theories and rejects both.\n\n**7.** **Text 1.** Critics often praise the poet Eleanor Vance for the musical regularity of her verse. Her steady rhythms and frequent rhymes, they note, make her poems easy to memorise.\n\n**Text 2.** Vance''s early poems are indeed highly regular, but readers who stop there miss her later collections, in which she drops rhyme almost entirely and lets line lengths vary sharply. That later work, I would argue, is her most original.\n\nBased on the texts, how would the author of Text 2 most likely respond to the critics in Text 1?\n- A) By noting that their description fits only part of Vance''s work and overlooks the later poems the author values most\n- B) By insisting that Vance''s poems are not regular in rhythm at all\n- C) By claiming that rhyme makes poems harder to memorise\n- D) By arguing that Vance''s early work is more original than her later work"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Drill: answers and explanations', '{"markdown":"**1. A.** The clue is the contrast with \"bold experiments\" and the explanation after the colon: quiet, simple forms. *Restrained* fits. B and C point the wrong way (disorderly, showy). D is unrelated to style.\n\n**2. A.** The colon explains: nearly every participant responded strongly, and regulators wanted more study. *Promising* fits. B contradicts the clear result. C means too small to matter, which would not justify a larger study. D adds a disagreement the passage never mentions.\n\n**3. B.** A medication that \"does not cure\" but buys \"valuable time\" stops or slows the disease, so *halt*. A and C are the everyday, police-related meanings of *arrest*, the classic trap. D has no connection.\n\n**4. A.** The passage gives the modern habit, then historical counterexamples, then notes the convention developed later. Its purpose is to show the orientation is a convention that has changed. B overstates; no recommendation is made. C is a side detail at most. D invents criticism; the text describes, it does not judge.\n\n**5. A.** The letters are cheerful, then \"Yet\" introduces an omission, and the mother notices \"what was missing\". The bold sentence complicates the cheerful impression. B is not stated. C invents an attitude. D describes the second sentence, not the bold one.\n\n**6. A.** Labels: ability (sentence 1), open question (sentence 2), finding (sentence 3), limitation (sentence 4, signalled by \"however\"). B and D invent content. C reverses the comparison; the passage says similar cells do not produce regeneration in mammals.\n\n**7. A.** Text 2 agrees the early poems are regular (\"indeed\") but says the critics miss the later, more original work. That is a qualification. B contradicts \"indeed highly regular\". C is never discussed. D reverses the author''s view.\n\nNote which trap caught you on each miss. Repeated traps show you exactly which habit to fix."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'A weekly practice routine', '{"markdown":"About 25 to 35 minutes a day, alongside the rest of your preparation:\n\n- **Day 1: words in context.** Fifteen questions. For each, write your predicted word before looking at the choices. Add every unknown word to your notebook with its sentence.\n- **Day 2: structure and purpose.** Ten questions. Label every sentence with a move before answering.\n- **Day 3: function questions.** Ten questions. Say what would be lost if the marked sentence were deleted.\n- **Day 4: cross-text.** Six to eight pairs. Write one-sentence summaries of both texts first.\n- **Day 5: mixed and timed.** Fifteen Craft and Structure questions, aiming for the timing table above.\n- **Day 6: vocabulary review and error log.** Revisit this week''s new words and redo every miss cold.\n- **Day 7: rest, or a full-length Bluebook practice test** if your plan schedules one.\n\nTilt the week toward whichever skill your practice results show as weakest."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Priorities by current section score', '{"markdown":"These are priorities by your current Reading and Writing section score, not promises of points; progress depends on your starting point, time and review quality.\n\n**Below about 500**\n- Make prediction a habit on every words-in-context question.\n- Learn common contrast and cause signals (*although*, *yet*, *however*, *because*, *thus*) and what they demand.\n- Start a vocabulary notebook from your own misses.\n\n**About 500 to 650**\n- Add second meanings of common words and the charge and strength of near-synonyms.\n- Label sentence moves on every structure and function question.\n- Practise cross-text pairs until one-sentence summaries feel natural.\n\n**Above about 650**\n- Focus on the hardest vocabulary, where two choices are close in meaning and only one is precise.\n- Practise older literary passages, where structure and tone are subtler.\n- In cross-text questions, check that the answer responds to exactly the claim named in the stem."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Frequently asked questions', '{"markdown":"### Will I see the same words-in-context words that appear on lists online?\nPossibly, but no list is official or complete. Learning words from your own practice misses, plus second meanings of common words, is more reliable than memorising a long list.\n\n### What if I do not know any of the words in the choices?\nPredict the meaning you need, use its charge (positive or negative) and eliminate any choice whose charge or sense you can rule out. Then choose, mark the question and move on.\n\n### Is the underlined sentence always the topic sentence?\nNo. A marked sentence can be a claim, an example, a contrast, a correction or a conclusion. Judge it by its relationship to the sentences around it.\n\n### Do cross-text authors usually disagree?\nOften they partly disagree, but the most common relationship is qualification: Text 2 accepts part of Text 1 and adds a limit or caution. Answers that make Text 2 hostile are frequently too strong."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Related practice', '{"markdown":"- [Words-in-context and Craft and Structure questions in the SAT Practice bank](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=vocabulary_in_context)\n- [Hard Craft and Structure questions](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=vocabulary_in_context&difficulty=hard)\n- [Today''s personalised practice session](https://practice.sat.schood.online/today)\n- [Take a full timed test in the SAT Simulator](https://sat.schood.online)\n\nOfficial free practice is also available as full-length adaptive tests in the Bluebook app and through Official Digital SAT Prep on Khan Academy."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'Next steps', '{"markdown":"- Continue with [Information and Ideas](https://playbook.sat.schood.online/reading-writing-information-ideas), the block that follows this one in every module.\n- Then study [Standard English Conventions](https://playbook.sat.schood.online/reading-writing-conventions) and [Expression of Ideas](https://playbook.sat.schood.online/reading-writing-expression-of-ideas).\n- Plan your pace across the whole section with [Pacing and Adaptive Modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules).\n- Set a realistic target with [Score Goals and Study Plans](https://playbook.sat.schood.online/score-goals-and-study-plans).\n- New to the test? Start with [SAT Essentials](https://playbook.sat.schood.online/sat-essentials)."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:reading-writing-craft-structure')::uuid
on conflict do nothing;

