-- Module 5: reading-writing-expression-of-ideas (27 sections, 5430 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:reading-writing-expression-of-ideas')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'reading-writing-expression-of-ideas', 'reading-writing-expression-of-ideas', 'Reading and Writing: Expression of Ideas', 'Rhetorical Synthesis and Transitions, the quickest points in the Reading and Writing section: a goal-first method for student-notes questions, a relationship-first method for transitions, original worked examples, traps, timing and a drill with answers.', 'published', 'public', 'en', 5, 'Reading and Writing: Expression of Ideas | SAT Playbook', 'How to answer Digital SAT Expression of Ideas questions: Rhetorical Synthesis from student notes and Transitions, with original worked examples, common traps, timing and a practice drill.', array['SAT', 'Digital SAT', 'Expression of Ideas', 'Rhetorical Synthesis', 'Transitions', 'SAT Reading and Writing']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"reading-writing-expression-of-ideas","module_group":"domain_reading_writing","migration_group":"reading_writing","hero_kicker":"Module 5","word_count":5430,"section_count":27,"reading_minutes":27,"estimated_reading_minutes":27,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Transitions practice set","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=transitions"},{"label":"Rhetorical Synthesis practice set","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=rhetoric"},{"label":"Hard Expression of Ideas questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=rhetoric&difficulty=hard"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:reading-writing-expression-of-ideas:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why this module matters', '{"markdown":"Expression of Ideas is the domain where the SAT asks you to think like a writer and an editor at the same time. You are not hunting for a grammar error, and you are not interpreting a poem. You are deciding which version of a sentence does the job a writer wants it to do: present a finding to a particular audience, contrast two things, explain a method, or connect one idea to the next with the right logical signal.\n\nThat makes these questions unusually **learnable**. The two skills in this domain, Rhetorical Synthesis and Transitions, follow a small number of repeatable patterns. Once you have a method, most of them take well under a minute, and the answer can be checked against something concrete on the screen: the stated goal in a notes question, or the relationship between two sentences in a transitions question.\n\nThis module gives you a **goal-first method** for Rhetorical Synthesis, a **relationship-first method** for Transitions, six original worked examples, the traps that cost the most points, timing targets and an eight-question drill with answers."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'Key outcomes', '{"items":["Find the Expression of Ideas questions at the end of each Reading and Writing module and budget time for them.","Read the goal in a Rhetorical Synthesis question before reading any of the notes or choices.","Reject accurate-but-irrelevant choices that use the notes without meeting the goal.","Recognise goal words such as emphasize, contrast, compare, explain, introduce and present.","Name the logical relationship between two sentences before looking at the transition choices.","Sort common transition words into their families: contrast, concession, cause and effect, addition, example, clarification and sequence.","Answer most Expression of Ideas questions in 30 to 60 seconds without guessing.","Review mistakes by naming the exact step that went wrong."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where these questions sit in a module', '{"markdown":"The digital SAT Reading and Writing section has two modules. Each module has **27 questions in 32 minutes**, and two of those questions in each module are unscored pretest items that look exactly like the others. Every module contains questions from all four content domains, and College Board publishes the order in which the domains appear:\n\n1. Craft and Structure (words in context, text structure and purpose, cross-text connections)\n2. Information and Ideas (central ideas, command of evidence, inferences)\n3. Standard English Conventions (punctuation, agreement, verb forms and other rules)\n4. **Expression of Ideas** (Transitions and Rhetorical Synthesis)\n\nSo Expression of Ideas questions are the **last block** of every module. Within the block, questions that test similar skills are grouped together and run roughly from easier to harder. Across the whole section, the official specification puts this domain at about **20% of questions, or 8 to 12 questions** over both modules. In practice that means you will usually meet a handful of these questions at the end of each module.\n\nThe position matters for pacing. If you spend too long on the inference questions in the middle of the module, the time you lose comes out of the fastest, most reliable points on the test. A later section of this module turns that into a concrete checkpoint."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'What the domain actually measures', '{"markdown":"Expression of Ideas questions test **revision**: improving the effectiveness of writing so that it meets a specific rhetorical goal. Two skills are measured.\n\n### Rhetorical Synthesis\n\nYou see a short set of bullet-point notes that a student has collected on a topic, followed by a goal. The question asks which choice uses relevant information from the notes to accomplish that goal. Every choice is usually a well-formed sentence, and most of them contain accurate information from the notes. Only one does what the goal asks.\n\n### Transitions\n\nYou see a short passage with a blank at the start of a sentence (or occasionally within it). The choices are transition words or phrases such as *however*, *for example*, *as a result* or *similarly*. The correct answer is the one that signals the actual logical relationship between the sentence with the blank and the text that comes before it.\n\nNeither skill is about vocabulary difficulty or grammar. A choice can be grammatically perfect and still be wrong because it does the wrong job."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Rhetorical Synthesis: how the question works', '{"markdown":"A typical notes question has three parts:\n\n- **The notes.** Four to six bullet points about a person, discovery, place, work of art, study or event. They are factual and neutral. Some are background; some are the facts the goal needs.\n- **The goal.** One sentence that tells you what the student wants the new sentence to do, for example to emphasize a similarity, to introduce a scientist to an unfamiliar audience, or to explain how a study was carried out.\n- **The choices.** Four sentences built from the notes.\n\nThe key insight is that **the notes are not the question; the goal is**. Students who read the notes carefully first often lose time and then pick the choice that sounds most complete or most interesting. The test is designed so that several choices are true to the notes. Truth is not enough. The answer must satisfy every part of the goal."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'The goal-first method', '{"markdown":"Use the same five steps every time:\n\n1. **Skip the notes and read the goal.** Find the sentence that begins with something like \"The student wants to...\"\n2. **Underline the task word and the target.** The task word is the verb (emphasize, contrast, introduce, explain, present, specify). The target is what it applies to (a similarity between two languages, the method of a study, the significance of a discovery).\n3. **Predict the shape of the answer.** A contrast needs two things and a difference. An introduction for an unfamiliar audience needs identifying information. A methodology answer needs what the researchers did, not what they found.\n4. **Test each choice against the goal only.** Ask \"Does this sentence do exactly that?\" Eliminate choices that do something else, even if they are accurate.\n5. **Glance at the notes only if two choices survive.** Usually you will not need to. When you do, check that the surviving choice does not misstate a note.\n\nThis method feels backwards at first, because school trains you to read the passage before the question. Here the notes are reference material. You read them only to settle a tie."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Reading the goal precisely', '{"markdown":"Small words in the goal decide the answer. Use this reference table.\n\n| Goal wording | What the correct sentence must contain | Typical wrong choice |\n|---|---|---|\n| emphasize a similarity between X and Y | both X and Y, plus what they share | facts about only one of them, or a difference |\n| contrast X and Y / emphasize a difference | both X and Y, plus how they differ on the named point | a similarity, or a difference on a different point |\n| introduce X to an audience unfamiliar with it | who or what X is (identifying context) | uses the name as if the reader already knows it |\n| present X to an audience already familiar with it | the new detail, without basic background | spends the sentence on background |\n| explain the method or approach of a study | what was done and how | the result or conclusion |\n| present the findings or conclusion | what was found | the method or the setting |\n| emphasize the significance or impact | why it mattered or what it changed | a plain description of what happened |\n| specify where, when or how much | that exact detail | a related but different detail |\n\n**Two habits make this table work.** First, treat every noun in the goal as a requirement: a goal that mentions \"two languages\" is not met by a sentence about one language. Second, notice the audience. If the goal says the audience is unfamiliar, a sentence that drops a name without context fails, even if everything in it is correct."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Worked example 1: emphasizing a reason (science)', '{"markdown":"**Notes**\n\n- The axolotl is a salamander native to lake systems near Mexico City.\n- Unlike most salamanders, it usually keeps its gills and stays in the water as an adult.\n- Axolotls can regrow lost limbs, including bone, muscle and nerves.\n- Medical researchers study axolotl regeneration for clues about how human tissue might be repaired.\n- Wild axolotl populations have declined sharply because of habitat loss and pollution.\n\n**Goal:** The student wants to emphasize a reason axolotls interest medical researchers.\n\n- **A)** Axolotls, which are native to lake systems near Mexico City, have seen their wild populations decline sharply.\n- **B)** Because axolotls can regrow limbs complete with bone, muscle and nerves, medical researchers study them for clues about human tissue repair.\n- **C)** Unlike most salamanders, axolotls usually keep their gills and remain in the water as adults.\n- **D)** The axolotl is a salamander that lives in water and can regrow lost limbs.\n\n**Answer: B.** The goal has two parts: a *reason* and *medical researchers*. Choice B gives the reason (regeneration of complete limbs) and connects it to the researchers'' interest.\n\n- **A** is accurate but is about conservation, not research.\n- **C** describes an unusual trait, but the notes never link gills to medical research.\n- **D** is the most tempting wrong answer. It mentions regeneration, but it never says why researchers care. It describes the animal; it does not state a reason for research interest.\n\nThe lesson: a choice that contains the right *fact* can still fail if it does not perform the *task*."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Worked example 2: contrasting two things (history and engineering)', '{"markdown":"**Notes**\n\n- The Brooklyn Bridge in New York City opened in 1883.\n- Its main span is about 1,596 feet long.\n- The Golden Gate Bridge in San Francisco opened in 1937.\n- Its main span is 4,200 feet long.\n- Both bridges use steel cables to support their decks.\n\n**Goal:** The student wants to contrast the main span lengths of the two bridges.\n\n- **A)** The Brooklyn Bridge opened in 1883, while the Golden Gate Bridge opened in 1937.\n- **B)** The Golden Gate Bridge''s 4,200-foot main span is more than twice as long as the Brooklyn Bridge''s main span of about 1,596 feet.\n- **C)** Both the Brooklyn Bridge and the Golden Gate Bridge use steel cables to support their decks.\n- **D)** The Golden Gate Bridge, which opened in San Francisco in 1937, has a main span of 4,200 feet.\n\n**Answer: B.** It names both bridges and states how their main spans differ.\n\n- **A** is a contrast, but of opening dates, not span lengths. This is the classic \"right task, wrong target\" trap.\n- **C** states a similarity, which is the opposite of the task.\n- **D** gives one bridge''s span, but a contrast needs two things.\n\nNotice that you did not need to read the notes in detail. The goal told you to look for both bridges, the word *span*, and a difference."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Worked example 3: introducing someone to an unfamiliar audience (arts)', '{"markdown":"**Notes**\n\n- Hildegard of Bingen was a German abbess who lived in the twelfth century.\n- She composed dozens of religious chants that are still performed today.\n- She also wrote *Ordo Virtutum*, a musical drama.\n- Her writings covered theology, medicine and natural history.\n\n**Goal:** The student wants to introduce Hildegard of Bingen''s music to an audience unfamiliar with her.\n\n- **A)** *Ordo Virtutum* remains one of Hildegard''s most discussed works.\n- **B)** Hildegard''s chants, like her writings on medicine and natural history, show the range of her interests.\n- **C)** Hildegard of Bingen, a twelfth-century German abbess, composed dozens of religious chants that are still performed today.\n- **D)** Still performed today, the chants were composed in the twelfth century.\n\n**Answer: C.** An unfamiliar audience needs to know who Hildegard was (a twelfth-century German abbess) and what music she made (religious chants still performed today). Choice C supplies both.\n\n- **A** assumes the reader already knows what *Ordo Virtutum* is and who Hildegard is.\n- **B** shifts the focus to the range of her interests and gives no identifying context.\n- **D** never names her, so an unfamiliar reader would not know whose chants these are.\n\nAudience goals are among the most reliable questions on the test once you know the rule: **unfamiliar audience means identify first.**"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Transitions: how the question works', '{"markdown":"A transitions question gives you two to five sentences with a blank where a transition belongs. The four choices are usually all real transition words, and all of them would be grammatical in the blank. The only question is **logic**: which word correctly signals how the new sentence relates to what came before?\n\nMost mistakes come from reading the choices too early. Every transition sounds reasonable when you plug it in and read quickly, because your brain fills in the logic it expects. The fix is to decide on the relationship yourself, in your own words, before you look at the options."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Name the relationship first', '{"markdown":"Use this four-step routine:\n\n1. **Read the sentence before the blank and the sentence with the blank.** Cover the choices if you can. Sometimes you need two earlier sentences; read as much as the logic requires.\n2. **Say the relationship in plain words.** For example: \"the second sentence contradicts the first,\" \"the second is an example of the first,\" or \"the second is a result of the first.\"\n3. **Pick the family.** Match your plain-words description to one of the transition families in the next section.\n4. **Choose the one choice from that family.** If two choices seem to be from the same family, look for a finer distinction such as contrast versus concession, or example versus clarification.\n\nA useful self-check: after you choose, read the two sentences with the transition and ask whether a careful writer would actually say that. \"Glaciers move slowly. *Therefore*, some advance only a few centimeters a day\" sounds fine at speed, but the second sentence does not follow from the first; it specifies it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Transition families reference', '{"markdown":"| Family | Relationship | Common words and phrases |\n|---|---|---|\n| Contrast | the new idea opposes or differs from the previous one | however, in contrast, by contrast, on the other hand, yet, conversely |\n| Concession | the new idea holds true despite the previous one | nevertheless, nonetheless, even so, still, regardless |\n| Cause and effect | the new idea is a result of the previous one | therefore, thus, as a result, consequently, accordingly, hence |\n| Addition | the new idea adds a further point in the same direction | moreover, furthermore, in addition, besides, also |\n| Similarity | the new idea is like the previous one | similarly, likewise, in the same way |\n| Example | the new idea is an instance of the previous claim | for example, for instance, to illustrate |\n| Clarification or specification | the new idea restates or makes the previous one more precise | in other words, that is, specifically, in fact |\n| Sequence or time | the new idea comes later, earlier or at the same time | later, previously, subsequently, meanwhile, finally, first |\n| Conclusion or summary | the new idea wraps up what came before | in conclusion, in short, ultimately, overall |\n\nTwo distinctions appear again and again in harder questions:\n\n- **Contrast versus concession.** *However* simply marks a difference. *Nevertheless* and *even so* say something remains true in spite of what was just said. If the first sentence presents an obstacle and the second says the thing happened anyway, concession is the better fit.\n- **Example versus specification.** *For example* introduces one instance of a broader claim. *Specifically* narrows the same claim to its precise details. If the second sentence tells you exactly what the first sentence meant, rather than giving one case among many, choose specification."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Worked example 4: contrast (social science)', '{"markdown":"For decades, many economic models assumed that workers carefully compare retirement savings options and choose the plan that best serves their long-term interests. ______ studies of workplace retirement plans have found that employees are far more likely to save when enrollment is automatic than when they must sign up themselves.\n\n- **A)** Similarly,\n- **B)** However,\n- **C)** For example,\n- **D)** Therefore,\n\n**Relationship in plain words:** the studies show behaviour that does not fit the assumption. If people carefully compared options, the default would not matter so much. That is a contrast.\n\n**Answer: B.**\n\n- **A** signals that the studies say the same thing as the models, which they do not.\n- **C** would make the studies an example of careful comparison, which reverses the logic.\n- **D** claims the findings follow from the assumption. They undercut it instead."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Worked example 5: cause and effect (history of technology)', '{"markdown":"In the 1450s, Johannes Gutenberg''s printing press made it possible to produce many identical copies of a text far faster than scribes could copy them by hand. ______ printed books gradually became less expensive, and reading spread beyond a small educated elite.\n\n- **A)** Nevertheless,\n- **B)** As a result,\n- **C)** In comparison,\n- **D)** For instance,\n\n**Relationship:** cheaper books and wider reading are consequences of faster production. Cause, then effect.\n\n**Answer: B.**\n\n- **A** would suggest books became cheaper despite faster production, which makes no sense.\n- **C** sets up a comparison, but nothing is being compared.\n- **D** would make cheaper books an example of faster copying. They are a consequence of it, not an instance of it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Worked example 6: specification, a harder case (urban planning)', '{"markdown":"The planning committee''s report on the city''s transit system was unusually blunt. ______ it concluded that the existing bus network could not serve the projected population of 2040 without a complete redesign of its routes.\n\n- **A)** Specifically,\n- **B)** Nonetheless,\n- **C)** Previously,\n- **D)** Alternatively,\n\n**Relationship:** the second sentence tells us exactly what the blunt report said. It does not oppose the first sentence, come before it in time, or offer a different option. It makes the first sentence precise.\n\n**Answer: A.**\n\n- **B** signals concession: something true despite the bluntness. Nothing in the second sentence works against the first.\n- **C** places the conclusion earlier in time than the report, which contradicts the passage.\n- **D** presents the second sentence as a different option, but there is only one report and one conclusion.\n\nMany students choose *for example*-style answers for passages like this, but there is no list of blunt statements here; the second sentence is the bluntness itself. That is the mark of specification."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Common traps', '{"markdown":"These are the patterns that make wrong answers attractive. Learn to name them during review.\n\n### In Rhetorical Synthesis\n\n- **The accurate distractor.** Every word of the choice is true to the notes, but it does not meet the goal. This is the most common trap by far.\n- **Right task, wrong target.** The goal asks for a contrast of sizes and the choice contrasts dates.\n- **Half the requirement.** The goal mentions two items and the choice covers one; the goal asks for a reason and the choice gives only a description.\n- **The kitchen-sink sentence.** A long choice that packs in most of the notes. Length feels thorough, but extra facts do not satisfy a goal.\n- **The missing context.** For an unfamiliar audience, a choice that uses a name or technical term without identifying it.\n- **The method-result swap.** Asked for a method, the choice states a finding, or the reverse.\n\n### In Transitions\n\n- **Plug-and-play reading.** Trying each word in the blank and picking the one that \"sounds best\" without naming the logic first.\n- **Reading only one sentence.** The relationship sometimes depends on the sentence two lines up.\n- **Contrast instead of concession** and **example instead of specification**, described in the families section.\n- **Reacting to a single word.** Seeing \"but\" or \"although\" inside the earlier sentence and assuming the blank must be a contrast. The contrast may already be finished."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'callout', 'Decision rules', '{"label":"Two rules that settle most Expression of Ideas questions","body":"For Rhetorical Synthesis, read the goal first and choose the only sentence that does every part of what the goal says, even if another choice is longer, more interesting or more detailed. For Transitions, say the relationship between the sentences in your own words before you read the choices, then pick the word whose family matches what you said."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'More decision rules for close calls', '{"markdown":"When two choices survive, use these tie-breakers:\n\n- **Every noun in the goal must appear in the answer, in substance.** If the goal says \"the two studies,\" the answer needs both studies.\n- **Extra information is neutral, missing information is fatal.** A correct choice can include a harmless detail beyond the goal. A choice that leaves out a required element is wrong.\n- **Prefer the plain relationship.** If a transition requires you to invent a story to make it fit, it is wrong. The right one fits the sentences as written.\n- **Check direction.** *As a result* points from cause to effect. If the earlier sentence is the effect and the new sentence gives the cause, you need a different word (or the passage is signalling explanation).\n- **Do not over-read tone.** Expression of Ideas questions are about logic and purpose, not whether a word sounds formal."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Timing guidance', '{"markdown":"The Reading and Writing section gives you 32 minutes for 27 questions in each module, an average of a little over 70 seconds per question. Expression of Ideas questions should come in well under that average, which is how they \"bank\" time for harder reading questions earlier in the module.\n\nReasonable targets once you have practised the methods:\n\n- **Transitions:** about 25 to 40 seconds each.\n- **Rhetorical Synthesis:** about 40 to 60 seconds each, because you may need to verify against the notes when two choices survive.\n\nBecause this domain comes last in each module, plan backwards. The conventions block and the Expression of Ideas block together make up roughly the last third of a module. A practical checkpoint is to reach the **first Standard English Conventions question with at least 10 to 12 minutes remaining**. If you are behind that checkpoint, make a quick best guess on the hard inference or evidence question you are stuck on, mark it for review, and move on. Bluebook''s question menu lets you return to marked questions before time expires in that module.\n\nNever leave an Expression of Ideas question blank because of time. College Board''s scoring guidance is that guessing is generally better than leaving a question unanswered, and these questions are designed to be answerable quickly."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'rich_text', 'Drill: eight original questions', '{"markdown":"Try all eight before checking the answers in the next section. Time yourself: aim for about six minutes in total.\n\n**1.** Honeybees communicate the location of food through a movement known as the waggle dance. ______ the angle of the dance relative to vertical on the honeycomb indicates the direction of the food relative to the sun.\n\n- A) In contrast,\n- B) Specifically,\n- C) Nevertheless,\n- D) Consequently,\n\n**2.** Early radio broadcasts could reach listeners only within a limited distance of a single transmitter. ______ a single speech could be heard across an entire country once networks began linking stations together through telephone lines.\n\n- A) Later,\n- B) Similarly,\n- C) For example,\n- D) In other words,\n\n**3.** Many desert plants store water in thick, fleshy tissue. The saguaro cactus, ______ can expand its pleated stem to hold hundreds of liters of water after a heavy rain.\n\n- A) for example,\n- B) however,\n- C) instead,\n- D) in conclusion,\n\n**4.** The novelist insisted that her book was not autobiographical. ______ readers who knew her childhood town recognized many of its streets, shops and even neighbors in the novel''s pages.\n\n- A) Accordingly,\n- B) Even so,\n- C) Likewise,\n- D) To illustrate,\n\n**5.** Notes: Marie Tharp was an American geologist and oceanographic cartographer. In the early 1950s, while plotting ocean-depth data, she identified a rift valley running along the Mid-Atlantic Ridge. At the time, many geologists rejected the theory of continental drift. Her finding became important evidence for the idea that the seafloor spreads apart. Goal: the student wants to emphasize the significance of Tharp''s discovery.\n\n- A) Marie Tharp was an American geologist and oceanographic cartographer who plotted ocean-depth data.\n- B) In the early 1950s, Marie Tharp identified a rift valley along the Mid-Atlantic Ridge.\n- C) Marie Tharp''s identification of a rift valley along the Mid-Atlantic Ridge provided important evidence for seafloor spreading at a time when many geologists rejected continental drift.\n- D) Many geologists in the early 1950s rejected the theory of continental drift.\n\n**6.** Notes: Esperanto is a constructed language created by L. L. Zamenhof and first published in 1887. Zamenhof hoped it would serve as an easy-to-learn international second language. Toki Pona is a constructed language created by Sonja Lang and first published online in 2001. Toki Pona uses a very small vocabulary of a little over one hundred root words. Goal: the student wants to emphasize a similarity between the two languages.\n\n- A) Esperanto was first published in 1887, more than a century before Toki Pona appeared online in 2001.\n- B) Both Esperanto and Toki Pona are constructed languages, each designed by a single creator: L. L. Zamenhof and Sonja Lang, respectively.\n- C) Toki Pona uses a very small vocabulary of a little over one hundred root words.\n- D) Zamenhof hoped Esperanto would become an easy-to-learn international second language.\n\n**7.** Notes (hypothetical study): A research team wanted to know whether a large city park lowers summer air temperatures nearby. The team placed temperature sensors at 40 sites at different distances from the park. The sensors recorded the air temperature every 10 minutes for three months. Sites within 200 meters of the park were, on average, cooler than sites farther away. Goal: the student wants to describe the study''s methodology.\n\n- A) Sites within 200 meters of the park were, on average, cooler than sites farther away.\n- B) The research team wanted to know whether a large city park lowers summer air temperatures nearby.\n- C) To find out whether the park cooled nearby areas, the team placed sensors at 40 sites at different distances from it and recorded air temperatures every 10 minutes for three months.\n- D) A large city park appears to lower summer air temperatures within about 200 meters.\n\n**8.** Notes: NASA launched the Voyager 1 space probe in 1977. In 2012, Voyager 1 became the first human-made object to enter interstellar space. The probe carries a gold-plated record with sounds and images from Earth. Decades after launch, it continues to send data back to Earth. Goal: the student wants to emphasize a first that Voyager 1 achieved.\n\n- A) Voyager 1 carries a gold-plated record with sounds and images from Earth.\n- B) Decades after its launch in 1977, Voyager 1 continues to send data back to Earth.\n- C) In 2012, Voyager 1, launched by NASA in 1977, became the first human-made object to enter interstellar space.\n- D) NASA launched the Voyager 1 space probe in 1977."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'Drill answers and explanations', '{"markdown":"**1. B (Specifically).** The second sentence describes exactly how the dance communicates location, making the first sentence precise. A and C signal opposition that is not there. D claims the angle is a result of the dance''s existence, which is not the relationship.\n\n**2. A (Later).** The passage moves from an early limitation to a later development. B says the two situations are alike, but they are opposites in reach. C would make nationwide broadcasts an example of local reach. D would make them a restatement of it.\n\n**3. A (for example).** The saguaro is one instance of a desert plant that stores water. B and C signal contrast, but the saguaro fits the pattern rather than breaking it. D presents the sentence as a summary, but it introduces a single case.\n\n**4. B (Even so).** Readers recognized real places despite the author''s insistence, which is concession. A claims recognition followed from her denial. C claims the two sentences say similar things. D would make the readers'' recognition an illustration of her claim, when it actually works against it.\n\n**5. C.** Significance requires saying why the discovery mattered, and C links the finding to evidence for seafloor spreading against prevailing doubt. A describes Tharp but not the discovery. B states what she found but not why it mattered. D gives context without the discovery.\n\n**6. B.** Only B states something the two languages share and names both. A is a difference (dates). C and D each describe only one language.\n\n**7. C.** A methodology answer describes what was done: the sensors, the 40 sites, the distances and the recording schedule. A and D are results. B is the research question, not the method.\n\n**8. C.** The goal asks for a first, and C states the 2012 milestone of being the first human-made object to enter interstellar space. A and B are notable facts but not firsts. D gives only the launch.\n\nIf you missed a question, write down which step failed: did you skip the goal, misread the target, name the wrong relationship, or confuse two families? Over a few weeks, that list usually shows that two or three traps account for most misses, and fixing those is quicker than doing more questions."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'A weekly practice routine', '{"markdown":"Expression of Ideas improves fastest with short, frequent sets rather than occasional long sessions. A simple weekly pattern:\n\n- **Two short sets a week (15 minutes each).** Ten to twelve mixed Transitions and Rhetorical Synthesis questions, timed at the targets in this module.\n- **One review session (20 minutes).** Go back through every miss and every lucky guess. For each, write one line: the goal or relationship, the trap you fell for, and the rule that would have saved you.\n- **One mixed-module rehearsal every one to two weeks.** Practise the domain at the end of a full 27-question set, so you experience it with a tired brain and a running clock, the way it appears on the real test.\n- **Build a transitions notebook.** Each time you meet a transition word you are unsure of, add it to its family with an original example sentence of your own.\n\nUse official Bluebook full-length practice tests to check that your pacing holds under real conditions, and use the Schood SAT Practice bank for focused skill sets."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Priorities by current level', '{"markdown":"Your priorities depend on where you are now. These are strategy priorities, not score promises.\n\n### Reading and Writing score under 500\n\n- Learn the transition families table until you can sort any common transition word in a few seconds.\n- Use the goal-first method on every notes question, even when it feels slow at first.\n- Make sure you reach the end of every module. Unanswered questions at the end are the most avoidable losses in the section.\n\n### Score from 500 to 650\n\n- Focus on the two fine distinctions: contrast versus concession, and example versus specification.\n- In notes questions, practise rejecting accurate distractors quickly. Track how often you choose a choice that is true but does not meet the goal.\n- Use time saved here to slow down on the inference and evidence questions earlier in the module.\n\n### Score above 650\n\n- Aim for near-automatic accuracy here. Misses at this level usually come from rushing, not from not knowing the method.\n- Watch for multi-part goals (for example, \"introduce X and emphasize Y\") and for transitions that depend on a sentence two lines back.\n- Treat this block as a buffer: finishing it efficiently gives you time to review the hardest questions you marked earlier."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'FAQ', '{"markdown":"### Do I ever need outside knowledge for these questions?\n\nNo. Rhetorical Synthesis questions are answered from the notes and the goal, and Transitions questions are answered from the logic of the passage. Background knowledge can actually mislead you if it tempts you to prefer a choice that says something true in the world but not in the notes.\n\n### Should I read all the notes before the goal?\n\nUsually not. Reading the goal first tells you what to look for, and in many questions you can eliminate three choices without reading the notes in detail. Use the notes to verify the last one or two choices.\n\n### What if two transitions seem to mean the same thing?\n\nIf two choices are from the same family, both would be equally correct, so the test avoids that. When two seem similar, look for the finer distinction: contrast or concession, example or specification, addition or similarity.\n\n### Are longer choices more likely to be right in notes questions?\n\nNo. Length is not evidence. A long choice often includes extra facts while missing one element the goal requires."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'Related practice', '{"markdown":"Practise the skills from this module with focused sets in Schood SAT Practice:\n\n- [Transitions practice set](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=transitions)\n- [Hard transitions questions](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=transitions&difficulty=hard)\n- [Rhetorical Synthesis practice set](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=rhetoric)\n- [Hard Rhetorical Synthesis questions](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=rhetoric&difficulty=hard)\n- [Today''s practice session](https://practice.sat.schood.online/today)\n- [Full timed practice in the Schood SAT Simulator](https://sat.schood.online)"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Next steps', '{"markdown":"Continue with the rest of the SAT Playbook:\n\n- [Reading and Writing: Standard English Conventions](https://playbook.sat.schood.online/reading-writing-conventions) covers the block that comes just before Expression of Ideas in every module.\n- [Reading and Writing: Information and Ideas](https://playbook.sat.schood.online/reading-writing-information-ideas) and [Reading and Writing: Craft and Structure](https://playbook.sat.schood.online/reading-writing-craft-structure) cover the first part of each module.\n- [Pacing and adaptive modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules) explains how module 1 affects module 2 and how to plan your time.\n- [Score goals and study plans](https://playbook.sat.schood.online/score-goals-and-study-plans) helps you set a target and choose a plan.\n- [SAT essentials](https://playbook.sat.schood.online/sat-essentials) gives the full picture of the test if you are just starting."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:reading-writing-expression-of-ideas')::uuid
on conflict do nothing;

