-- Module 6: reading-writing-conventions (30 sections, 4750 words) ------------
insert into public.sat_playbook_pages (id, product_id, parent_page_id, page_type, module_key, slug, title, summary, status, visibility, locale_code, sort_order, seo_title, seo_description, seo_keywords, published_at, metadata)
values (md5('schood-sat-pb-page:reading-writing-conventions')::uuid, 'a8b41e2c-9a36-4caf-9bba-7212e35a8b8c'::uuid, null, 'module', 'reading-writing-conventions', 'reading-writing-conventions', 'Reading and Writing: Standard English Conventions', 'Boundaries and Form, Structure, and Sense on the Digital SAT: a clause-first method, a punctuation decision table, agreement, tense, possessive and modifier rules, original worked examples, traps, timing and a drill with answers.', 'published', 'public', 'en', 6, 'Reading and Writing: Standard English Conventions | SAT Playbook', 'Digital SAT grammar and punctuation explained: sentence boundaries, commas, semicolons, colons, dashes, subject-verb agreement, pronouns, verb tense, possessives and modifiers, with original examples and a drill.', array['SAT', 'Digital SAT', 'SAT grammar', 'Standard English Conventions', 'SAT punctuation', 'Boundaries', 'Form Structure and Sense']::text[], '2026-10-24T00:00:00Z'::timestamptz, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1","original_slug":"reading-writing-conventions","module_group":"domain_reading_writing","migration_group":"reading_writing","hero_kicker":"Module 6","word_count":4750,"section_count":30,"reading_minutes":24,"estimated_reading_minutes":24,"section_kinds":["rich_text","checklist","callout"],"related_practice":[{"label":"Conventions practice set","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=grammar"},{"label":"Hard conventions questions","url":"https://practice.sat.schood.online/bank?section_type=reading_writing&domain=grammar&difficulty=hard"},{"label":"Today''s practice session","url":"https://practice.sat.schood.online/today"}],"last_verified":"2026-10-24","verification_status":"verified","editorial":"original-schood"}'::jsonb)
on conflict do nothing;

insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select md5('schood-sat-pb-section:reading-writing-conventions:' || s.n)::uuid, p.id, s.block_type, s.heading, 'published', s.n, s.content, s.metadata
from public.sat_playbook_pages p
cross join (values
  (1, 'rich_text', 'Why this module matters', '{"markdown":"Standard English Conventions is the most rule-based domain on the digital SAT. The questions ask you to complete a short text so that it follows the conventions of written Standard English: where sentences begin and end, how punctuation joins or separates ideas, and whether words agree in number, tense and form.\n\nBecause the rules are finite, this is the domain where steady study turns into reliable points. Students who struggle with it usually do not lack intelligence or reading skill; they are relying on what \"sounds right,\" and the test is built so that sound is not enough. A comma can sound like a natural pause and still create a comma splice. A verb can sound fine next to the nearest noun and still disagree with its real subject.\n\nIn this module you will learn:\n\n- How to identify **clauses and phrases** quickly, which is the foundation of every punctuation question.\n- A **punctuation decision table** for periods, semicolons, commas, colons and dashes.\n- The **agreement, tense, possessive and modifier rules** the test returns to most often.\n- Six original worked examples with every wrong choice explained, common traps, timing targets and an eight-question drill with answers."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (2, 'checklist', 'Key outcomes', '{"items":["Find the conventions block in each module and know how much time to give it.","Identify independent clauses, dependent clauses and phrases in a sentence within seconds.","Join two independent clauses correctly and recognise comma splices, run-ons and fragments.","Use colons and single dashes only after a complete independent clause.","Punctuate supplementary phrases with a matching pair of commas, dashes or parentheses.","Avoid unnecessary commas between a subject and its verb or a verb and its object.","Make verbs agree with their true subject, even when a long phrase separates them.","Choose pronouns and possessive determiners that match their antecedents.","Choose verb tenses that fit the time signals in the passage.","Distinguish plural, singular possessive and plural possessive forms.","Fix dangling and misplaced modifiers by matching the modifier to the right noun."]}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (3, 'rich_text', 'Where conventions questions sit', '{"markdown":"Each Reading and Writing module has **27 questions in 32 minutes**, including two unscored pretest questions that look like any other. The domains appear in a fixed order: Craft and Structure, then Information and Ideas, then **Standard English Conventions**, then Expression of Ideas.\n\nTwo facts from the official specification shape your strategy:\n\n- The domain is about **26% of the section**, roughly **11 to 15 questions** across both modules, so about half of that range in each module.\n- Unlike the other domains, conventions questions are **not grouped by skill**. They run from easiest to hardest regardless of which rule is being tested. A comma question can be followed by an agreement question and then a colon question.\n\nSo you cannot switch into \"comma mode\" for a run of questions. You need a quick way to diagnose what each question is testing. The rest of this module gives you that diagnosis.\n\n### The two skills\n\nCollege Board divides the domain into two skills.\n\n#### Boundaries\n\nBoundaries questions are about **punctuation that marks the edges** of sentences, clauses and phrases. The choices usually contain the same words with different punctuation: a period, a semicolon, a comma, a colon, a dash, a comma plus a conjunction, or no punctuation at all. The task is to put the right boundary between the parts of the sentence.\n\n#### Form, Structure, and Sense\n\nThese questions are about **word forms** in context: subject-verb agreement, pronoun-antecedent agreement, verb tense and aspect, plurals and possessives, and the placement of modifiers so that the sentence makes logical sense. The choices usually contain different forms of the same word, such as *is/are/were/have been*, or the same idea arranged in different orders."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (4, 'rich_text', 'How to read a conventions question', '{"markdown":"Use this routine on every question:\n\n1. **Look at the choices first.** What changes between them? If only punctuation changes, it is a Boundaries question. If verb forms change, think agreement or tense. If apostrophes change, think plurals and possessives. If the order of words changes after an introductory phrase, think modifiers.\n2. **Read the whole sentence, not just the blank.** Agreement and modifier errors depend on words that may be far from the blank.\n3. **Locate the structure.** For punctuation, mark where each clause starts and ends. For verbs, find the true subject. For pronouns, find the antecedent. For modifiers, find who or what is doing the action.\n4. **Apply the rule, then eliminate.** Cross out choices that break the rule. Bluebook''s option eliminator is useful here.\n5. **Do not choose by ear.** If two choices both sound acceptable, return to the rule."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (5, 'rich_text', 'Sentence building blocks', '{"markdown":"Every Boundaries question depends on three ideas.\n\n- An **independent clause** has a subject and a verb and can stand alone as a sentence. *The festival began at noon.*\n- A **dependent clause** has a subject and a verb but begins with a word that makes it unable to stand alone, such as *because, although, when, which, that, who, if, while*. *Because the festival began at noon...*\n- A **phrase** lacks a subject-verb pair. *After the opening speech*, *a retired engineer from Samarkand*, *running late*.\n\nQuick tests:\n\n- Could the group of words be a complete sentence by itself, followed by a period? Then it is an independent clause.\n- Does it begin with a subordinating word or relative pronoun? Then it is dependent, even if it has a subject and verb.\n- Is there no conjugated verb at all? Then it is a phrase.\n\nWords like *however, therefore, moreover* and *for example* do **not** turn an independent clause into a dependent one. \"However, the festival began late\" is still a complete sentence. This is why \"the festival was planned for noon, however, it began late\" is a comma splice."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (6, 'rich_text', 'Punctuation decision table', '{"markdown":"Use this table as your rules reference. \"IC\" means independent clause.\n\n| What you are joining or marking | Correct options | Incorrect options |\n|---|---|---|\n| IC + IC | period; semicolon; comma + and/but/or/nor/for/so/yet; colon or dash if the second explains the first | comma alone (comma splice); nothing (run-on) |\n| IC + however/therefore + IC | period or semicolon before the adverb, comma after it | comma before the adverb |\n| Dependent clause first, then IC | comma after the dependent clause | semicolon; period (creates a fragment) |\n| IC, then a list, explanation or example | colon or single dash after the complete IC | colon after a verb or preposition, such as \"includes:\" |\n| Supplementary (nonessential) element in the middle | matching pair of commas, dashes or parentheses | mixed pair, such as a comma then a dash; only one mark |\n| Essential element (needed to identify the noun) | no commas | commas around it |\n| Items in a series | commas between items; semicolons if items contain commas | missing comma between two items |\n| Subject and its verb; verb and its object | no punctuation | a comma or other mark splitting them |\n\nTwo rules on this table deserve memorising word for word:\n\n- **A semicolon works like a period.** If you could not put a period there, you cannot put a semicolon there.\n- **A colon needs a complete sentence before it.** What comes after a colon can be a list, a phrase or a full clause, but what comes before must stand alone."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (7, 'rich_text', 'Joining two independent clauses', '{"markdown":"The most common Boundaries question puts a blank between two independent clauses. Original examples:\n\n- Correct: *The orchard flooded in April. Most of the trees survived.*\n- Correct: *The orchard flooded in April; most of the trees survived.*\n- Correct: *The orchard flooded in April, but most of the trees survived.*\n- Incorrect (comma splice): *The orchard flooded in April, most of the trees survived.*\n- Incorrect (run-on): *The orchard flooded in April most of the trees survived.*\n\nA **colon** or **single dash** can also join two independent clauses when the second explains, illustrates or completes the first: *The cause was clear: the river had overflowed its banks.*\n\nWhen a conjunctive adverb such as *however* sits between the two clauses, the boundary goes **before** it: *The orchard flooded in April; however, most of the trees survived.* If a choice puts only a comma before *however*, it is a comma splice.\n\nA **fragment** is the opposite problem: a group of words punctuated as a sentence when it is not one. *Because the orchard flooded in April.* If a choice creates a fragment with a period or semicolon, eliminate it."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (8, 'rich_text', 'Supplements, essential elements and series', '{"markdown":"A **supplement** is extra information that could be removed without breaking the sentence: *The engineer, who had designed three earlier bridges, approved the plan.* Remove the middle part and the sentence still works.\n\nSupplements need a **matching pair** of marks:\n\n- *The engineer, a graduate of a small technical college, approved the plan.*\n- *The engineer (a graduate of a small technical college) approved the plan.*\n- *The engineer—a graduate of a small technical college—approved the plan.*\n\nMixed pairs such as a comma followed by a dash are wrong. A common SAT pattern places the blank at the **end** of a supplement. Look left: if the supplement opened with a comma, it must close with a comma.\n\nAn **essential** element identifies which person or thing you mean, so it takes no commas: *The student who won the prize spoke first.* Without \"who won the prize,\" we would not know which student. Titles and names often follow this rule: *the novelist Willa Cather* takes no commas, because \"the novelist\" alone does not tell us which novelist.\n\nFor **series**, separate items with commas, and switch to semicolons when the items already contain commas: *The tour stopped in Bukhara, Uzbekistan; Almaty, Kazakhstan; and Bishkek, Kyrgyzstan.*\n\nFinally, remember the commas you must **not** use: never separate a subject from its verb (*The old maps of the region, were inaccurate* is wrong) or a verb from its object or complement."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (9, 'rich_text', 'Worked example 1: joining clauses (earth science)', '{"markdown":"Glaciers move more slowly than most people ______ some advance only a few centimeters a day.\n\n- **A)** imagine,\n- **B)** imagine;\n- **C)** imagine\n- **D)** imagine, and,\n\n**Diagnosis:** only punctuation changes, so this is Boundaries. \"Glaciers move more slowly than most people imagine\" is independent. \"Some advance only a few centimeters a day\" is also independent.\n\n**Answer: B.** A semicolon correctly joins two independent clauses.\n\n- **A** is a comma splice: two independent clauses joined by a comma alone.\n- **C** is a run-on with no punctuation at all.\n- **D** uses a conjunction, which would be acceptable as \", and\", but the extra comma after \"and\" is not standard."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (10, 'rich_text', 'Worked example 2: closing a supplement (history)', '{"markdown":"Ida B. Wells, a journalist who investigated lynching in the American South during the ______ later became one of the founders of the NAACP.\n\n- **A)** 1890s,\n- **B)** 1890s;\n- **C)** 1890s\n- **D)** 1890s—\n\n**Diagnosis:** a supplement begins after \"Ida B. Wells,\" with a comma. The blank is the end of that supplement, just before the main verb \"later became.\"\n\n**Answer: A.** The supplement opened with a comma, so it must close with a comma.\n\n- **B** puts a semicolon between the subject and its verb; \"Ida B. Wells, a journalist...\" is not an independent clause.\n- **C** leaves the supplement open, which makes it read as if \"the 1890s later became one of the founders.\"\n- **D** mixes a comma with a dash. The pair must match."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (11, 'rich_text', 'Subject-verb agreement', '{"markdown":"A verb must agree in number with its **true subject**, not with the nearest noun. The test hides the subject in four main ways:\n\n- **Intervening phrases.** *The collection of letters from the 1920s **is** on display.* The subject is \"collection,\" not \"letters.\"\n- **Relative clauses.** *The scientist who studies these frogs **travels** often.* The subject of \"travels\" is \"scientist.\"\n- **Inverted order.** *Along the riverbank **grow** several species of willow.* The subject, \"species,\" comes after the verb.\n- **Indefinite pronouns and \"each.\"** *Each of the reports **was** reviewed. Neither of the routes **is** open.* \"Each,\" \"every,\" \"either,\" \"neither,\" \"one\" and \"everyone\" are singular.\n\nCollective nouns such as *team, committee, population, jury* and *audience* are treated as singular on the SAT when they act as a unit: *The committee **has** approved the budget.*\n\n**Method:** cross out every prepositional phrase and every relative clause between the subject and the verb. What remains should read as a short, simple sentence."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (12, 'rich_text', 'Pronouns and possessive determiners', '{"markdown":"Pronouns must agree with their **antecedents** in number, and possessive forms must be spelled correctly.\n\n- A singular antecedent takes a singular pronoun: *The museum opened **its** new wing.* A company, city, government, museum or team is \"it,\" not \"they,\" on the SAT.\n- A plural antecedent takes a plural pronoun: *The museums opened **their** new wings.*\n- **It''s** means \"it is\" or \"it has.\" **Its** is the possessive. There is no word \"its''.\"\n- **They''re** means \"they are.\" **Their** is possessive. **There** is a place or introduces a sentence.\n- **Who''s** means \"who is.\" **Whose** is possessive.\n\nA useful check: expand the contraction. If \"it is\" does not fit, the answer cannot be \"it''s.\""}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (13, 'rich_text', 'Verb tense and aspect', '{"markdown":"Choose the verb form that fits the **time signals** in the passage: dates, words such as *since, by the time, currently, last year*, and the tense of nearby verbs.\n\n| Form | Use | Original example |\n|---|---|---|\n| Simple past | a completed action at a specific past time | In 1923, the archive **opened** to the public. |\n| Present perfect | an action continuing from the past to now, often with \"since\" or \"for\" | Since 2015, the team **has identified** many new species. |\n| Past perfect | an action completed before another past action | By the time the rains arrived, the farmers **had planted** the seeds. |\n| Simple present | general truths, habits and descriptions of a text or work | The novel **follows** a family across three generations. |\n| Future perfect | an action that will be complete before a future time | By 2030, the line **will have carried** millions of passengers. |\n\nTwo reminders: keep a sequence of related actions in the same tense unless the passage signals a time change, and use the present tense to describe what an author, artwork or study *does* in a text (\"the essay argues\")."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (14, 'rich_text', 'Plurals and possessives', '{"markdown":"Apostrophes show possession, not plurality.\n\n| Form | Meaning | Original example |\n|---|---|---|\n| researcher | one researcher | The researcher took notes. |\n| researchers | more than one researcher | The researchers took notes. |\n| researcher''s | belonging to one researcher | The researcher''s notes were detailed. |\n| researchers'' | belonging to more than one researcher | The researchers'' notes were compared. |\n| children''s | belonging to children (irregular plural + ''s) | The children''s library reopened. |\n\n**Method:** ask two questions. Is there more than one? Does the word own the next noun? If the next word is a noun that belongs to this word, you need an apostrophe; if not, you need a plain plural or singular. Then use clues in the sentence, such as \"its\" or \"their,\" to decide singular or plural."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (15, 'rich_text', 'Modifiers that make sense', '{"markdown":"An introductory modifying phrase must be followed immediately by the noun it describes.\n\n- Wrong: *Walking through the market, the smell of fresh bread surprised us.* (The smell was not walking.)\n- Right: *Walking through the market, we were surprised by the smell of fresh bread.*\n\nIn SAT questions, the modifier is usually given before the blank and the choices rearrange the rest of the sentence. **Method:** ask \"who or what is doing the action in the opening phrase?\" The correct choice begins with that noun. Choices that begin with a possessive (*Michelangelo''s work*) or with a different noun are dangling, even if they sound sophisticated."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (16, 'rich_text', 'Worked example 3: agreement with a hidden subject (biology)', '{"markdown":"The population of monarch butterflies that spend the winter in the forests of central Mexico ______ sharply over recent decades.\n\n- **A)** have declined\n- **B)** has declined\n- **C)** are declining\n- **D)** decline\n\n**Diagnosis:** verb forms change, so find the subject. Cross out \"of monarch butterflies\" and the relative clause \"that spend the winter in the forests of central Mexico.\" What remains: \"The population ______ sharply.\"\n\n**Answer: B.** \"Population\" is singular, and \"over recent decades\" signals an action continuing to the present, which fits the present perfect.\n\n- **A**, **C** and **D** are all plural forms that agree with \"butterflies,\" the nearest noun, rather than the true subject."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (17, 'rich_text', 'Worked example 4: dangling modifier (art history)', '{"markdown":"Painted over the course of about four years, ______\n\n- **A)** Michelangelo completed the Sistine Chapel ceiling in 1512.\n- **B)** the Sistine Chapel ceiling was completed by Michelangelo in 1512.\n- **C)** in 1512 Michelangelo completed the Sistine Chapel ceiling.\n- **D)** Michelangelo''s completion of the Sistine Chapel ceiling came in 1512.\n\n**Diagnosis:** the opening phrase describes something that was *painted*. What was painted? The ceiling.\n\n**Answer: B.** The noun right after the comma, \"the Sistine Chapel ceiling,\" is the thing that was painted.\n\n- **A** says Michelangelo was painted over four years.\n- **C** puts \"in 1512\" right after the modifier, so the phrase describes a year.\n- **D** makes the modifier describe \"Michelangelo''s completion,\" which was not painted. Possessive openings are a classic dangling-modifier trap."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (18, 'rich_text', 'Worked example 5: possessive with a context clue (economics)', '{"markdown":"The ______ decision to publish salary ranges in every job posting surprised many of its competitors.\n\n- **A)** companies\n- **B)** company''s\n- **C)** companies''\n- **D)** companys\n\n**Diagnosis:** the word owns \"decision,\" so it needs an apostrophe. The clue \"its competitors\" tells us there is one company.\n\n**Answer: B.** Singular possessive.\n\n- **A** is a plain plural with no possession.\n- **C** is plural possessive, but \"its\" shows the company is singular.\n- **D** is not a standard spelling of any form."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (19, 'rich_text', 'Worked example 6: past perfect (literature)', '{"markdown":"When Willa Cather published the novel *My Ántonia* in 1918, she ______ in Nebraska for several years as a child, and the novel draws on the prairie landscapes she remembered.\n\n- **A)** has lived\n- **B)** had lived\n- **C)** lives\n- **D)** will have lived\n\n**Diagnosis:** verb tense changes. The living in Nebraska happened before another past event, the 1918 publication.\n\n**Answer: B.** The past perfect marks an action completed before another past action.\n\n- **A** is present perfect, which connects to the present, not to 1918.\n- **C** is present tense, which contradicts the past setting.\n- **D** is future perfect, which points forward from now.\n\nNotice that \"draws\" later in the sentence is correct as simple present, because it describes what the novel does as a text."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (20, 'rich_text', 'Common traps', '{"markdown":"- **The pause trap.** A comma placed where you would breathe when reading aloud. Breathing is not a rule; clause structure is.\n- **The nearest-noun trap.** A verb that agrees with the noun just before it instead of the true subject.\n- **The however splice.** \"..., however, ...\" between two independent clauses.\n- **The colon after an incomplete clause.** \"The kit includes: a tent, a stove and a map.\" Nothing should separate \"includes\" from its objects.\n- **The mismatched pair.** A supplement opened with a dash and closed with a comma, or opened and never closed.\n- **The plural-they trap.** \"The council announced their plan\" when the SAT expects the singular \"its.\"\n- **The possessive opening.** A modifier followed by \"Michelangelo''s work\" or \"the city''s decision\" instead of the actual actor.\n- **The tense-by-ear trap.** Choosing simple past after \"since\" or ignoring \"by the time.\"\n- **The fancy punctuation trap.** Assuming a semicolon or dash is more sophisticated and therefore more likely to be right."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (21, 'callout', 'Decision rules', '{"label":"The clause-first rule","body":"Before choosing any punctuation, decide whether each side of the blank is an independent clause, a dependent clause or a phrase. A period, semicolon, or comma with a coordinating conjunction can join two independent clauses; a colon or single dash needs a complete independent clause before it; a comma alone can never join two independent clauses. If you cannot name what is on each side, you are not ready to choose."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (22, 'rich_text', 'More rules for close calls', '{"markdown":"- **If two choices would be equally correct, rethink the structure.** A period and a semicolon do the same job between two independent clauses, and a question with a single best answer cannot hinge on choosing between them. If both appear among the choices, the boundary is probably not between two independent clauses.\n- **Shorter is not automatically right, but extra punctuation needs a reason.** If you cannot name the rule that requires a mark, choose the version without it.\n- **Read past the blank.** The end of the sentence often reveals whether the blank is inside a supplement or between clauses.\n- **Use the passage''s own clues.** \"Its,\" \"their,\" dates and other verbs in the same passage are deliberate signals."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (23, 'rich_text', 'Timing guidance', '{"markdown":"With 32 minutes for 27 questions, the average is a little over 70 seconds per question. Conventions questions should be much faster:\n\n- **Most conventions questions:** about 20 to 40 seconds once you know the rules.\n- **The hardest ones near the end of the block:** up to about 60 seconds, usually because the sentence is long or the structure is unusual.\n\nBecause conventions and Expression of Ideas come at the end of each module, they share the time you have left. A practical target is to reach the **first conventions question with at least 10 to 12 minutes remaining**. If you arrive with less, keep working at full speed: these are the questions where speed and accuracy go together once the rules are automatic.\n\nIf a conventions question resists you for more than a minute, choose your best answer, mark it for review and move on. Guessing is generally better than leaving a question blank, according to College Board''s scoring guidance, and you can return to marked questions with the question menu before the module ends."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (24, 'rich_text', 'Drill: eight original questions', '{"markdown":"Choose the option that completes the text so that it follows Standard English conventions. Aim for about five minutes in total.\n\n**1.** The Atacama Desert in northern Chile is one of the driest places on ______ some weather stations there have recorded almost no rainfall over many years.\n\n- A) Earth,\n- B) Earth;\n- C) Earth\n- D) Earth, which\n\n**2.** The octopus—an animal with no internal or external ______ can squeeze through openings only slightly larger than its beak.\n\n- A) skeleton—\n- B) skeleton,\n- C) skeleton\n- D) skeleton;\n\n**3.** Each of the paintings in the museum''s new wing ______ accompanied by a label in three languages.\n\n- A) is\n- B) are\n- C) were\n- D) have been\n\n**4.** After years of planning and fundraising, the city museum finally opened ______ new science wing to the public in March.\n\n- A) its\n- B) it''s\n- C) their\n- D) its''\n\n**5.** Since 2015, the research team ______ more than two hundred species of beetles in the nature reserve.\n\n- A) identifies\n- B) has identified\n- C) identified\n- D) will identify\n\n**6.** Having traveled thousands of kilometers from southern Canada, ______\n\n- A) the forests of central Mexico were finally reached by the butterflies.\n- B) the butterflies finally reached the forests of central Mexico.\n- C) the journey of the butterflies finally ended in central Mexico.\n- D) central Mexico''s forests finally welcomed the butterflies.\n\n**7.** The two ______ shared notebook, filled with sketches of the river delta, was donated to the university library after the expedition.\n\n- A) explorer''s\n- B) explorers\n- C) explorers''\n- D) explorer\n\n**8.** The expedition carried three essential ______ a satellite phone, a solar charger and a water filter that could remove bacteria.\n\n- A) tools:\n- B) tools;\n- C) tools\n- D) tools, such as:"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (25, 'rich_text', 'Drill answers and explanations', '{"markdown":"**1. B.** Both sides are independent clauses, and a semicolon joins them. A is a comma splice. C is a run-on. D creates \"which some weather stations there have recorded almost no rainfall,\" which is not a grammatical clause.\n\n**2. A.** The supplement opened with a dash after \"octopus,\" so it must close with a dash. B and D mismatch the pair, and D also puts a semicolon between the subject and its verb. C leaves the supplement unclosed.\n\n**3. A.** \"Each\" is singular, so the verb is \"is.\" B, C and D are plural forms that agree with \"paintings,\" the nearest noun. C also shifts to the past tense without a reason.\n\n**4. A.** The museum is singular and owns the wing, so the possessive \"its\" is correct. B means \"it is.\" C is plural. D is not a word.\n\n**5. B.** \"Since 2015\" describes an action continuing up to now, which calls for the present perfect. A is simple present and C is simple past, neither of which fits \"since.\" D points to the future.\n\n**6. B.** The butterflies did the traveling, so \"the butterflies\" must follow the comma. A and D make the forests the travelers. C makes \"the journey\" the traveler.\n\n**7. C.** \"Two\" tells us there is more than one explorer, and the notebook belongs to them, so the plural possessive \"explorers''\" is correct. A and D are singular, which conflicts with \"two.\" B is a plain plural with no possession; it would make \"shared\" read as a verb and leave \"was donated\" without a subject.\n\n**8. A.** \"The expedition carried three essential tools\" is a complete independent clause, and a colon introduces the list that explains it. B uses a semicolon, which needs an independent clause after it. C runs the list into the clause with no boundary. D places a colon after \"such as,\" which is not a complete clause, and \"such as\" would also imply the list is incomplete.\n\nFor every miss, write the rule in one sentence. Your error log becomes your personal grammar book."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (26, 'rich_text', 'A weekly practice routine', '{"markdown":"Conventions reward repetition with immediate feedback. A sustainable weekly plan:\n\n- **Rules review (10 minutes, twice a week).** Reread the decision table and one rule section. Write two original sentences that follow the rule and one that breaks it, then fix it.\n- **Mixed sets (15 minutes, three times a week).** Twelve to fifteen mixed conventions questions, timed at about 30 seconds each. Mixed order matters, because the real test does not group conventions questions by skill.\n- **Error log (10 minutes, once a week).** Sort your misses by rule. If one rule keeps appearing, give it a focused set the following week.\n- **Full-module rehearsal (every one to two weeks).** Practise conventions at the end of a 27-question set with the clock running, ideally in an official Bluebook practice test or the Schood SAT Simulator."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (27, 'rich_text', 'Priorities by current level', '{"markdown":"These are priorities for study time, not predictions of score gains.\n\n### Reading and Writing score under 500\n\n- Master independent clauses and the comma splice first. Many questions depend on this one idea.\n- Learn the basic apostrophe table and its/it''s.\n- Practise finding the true subject by crossing out phrases.\n\n### Score from 500 to 650\n\n- Add colons, dashes and supplements. The matching-pair rule is a frequent decider.\n- Practise tense questions that use \"since,\" \"by the time\" and dates.\n- Start timing your sets so that conventions take well under the section average.\n\n### Score above 650\n\n- The hardest questions at the end of the block often combine long sentences with supplements or inverted subjects. Map the structure on scratch paper if needed.\n- Watch for essential versus nonessential elements, such as titles before names.\n- Aim for automatic accuracy so this block funds extra review time for the hardest reading questions."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (28, 'rich_text', 'FAQ', '{"markdown":"### Is there a list of every rule the SAT tests?\n\nCollege Board names the two skills, Boundaries and Form, Structure, and Sense, and its Assessment Framework describes them in detail. The rules in this module cover the patterns those skill definitions describe. You do not need obscure grammar terms; you need to recognise structures.\n\n### Does the SAT test the Oxford comma?\n\nThe serial comma before \"and\" in a list of three or more is a style choice, and both versions are generally acceptable. Questions are designed to have a single best answer, so a correct answer should not depend on a style preference. Focus on the rules that are clearly right or wrong.\n\n### Should I trust my ear at all?\n\nYour ear is a good first alarm but a poor judge. Use it to notice that something might be wrong, then confirm with a rule.\n\n### Why are conventions questions mixed instead of grouped?\n\nThe official specification arranges conventions questions from easiest to hardest regardless of the convention tested. That is why the diagnostic step, looking at what changes between the choices, matters so much.\n\n### Will the test ever have two right answers?\n\nEach question has a single best answer. If two choices look equally correct, look again at the structure around the blank; usually one side is not what you assumed."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (29, 'rich_text', 'Related practice', '{"markdown":"Practise the rules from this module with focused sets in Schood SAT Practice:\n\n- [Conventions practice set](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=grammar)\n- [Hard conventions questions](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=grammar&difficulty=hard)\n- [Easy conventions warm-up](https://practice.sat.schood.online/bank?section_type=reading_writing&domain=grammar&difficulty=easy)\n- [Today''s practice session](https://practice.sat.schood.online/today)\n- [Full timed practice in the Schood SAT Simulator](https://sat.schood.online)"}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb),
  (30, 'rich_text', 'Next steps', '{"markdown":"Continue with the rest of the SAT Playbook:\n\n- [Reading and Writing: Expression of Ideas](https://playbook.sat.schood.online/reading-writing-expression-of-ideas) covers the block that follows conventions at the end of every module.\n- [Reading and Writing: Craft and Structure](https://playbook.sat.schood.online/reading-writing-craft-structure) and [Reading and Writing: Information and Ideas](https://playbook.sat.schood.online/reading-writing-information-ideas) cover the first part of each module.\n- [Pacing and adaptive modules](https://playbook.sat.schood.online/pacing-and-adaptive-modules) shows how to plan time across a module.\n- [Test-day guide](https://playbook.sat.schood.online/test-day-guide) explains Bluebook tools such as the option eliminator and question menu.\n- [SAT essentials](https://playbook.sat.schood.online/sat-essentials) gives the full picture of the test."}'::jsonb, '{"seeded_by":"sat-pb-modules","content_revision":"sat-pb-public-v1"}'::jsonb)
) as s(n, block_type, heading, content, metadata)
where p.id = md5('schood-sat-pb-page:reading-writing-conventions')::uuid
on conflict do nothing;

