  ('https://satsuite.collegeboard.org/media/pdf/assessment-framework-for-digital-sat-suite.pdf', 3, 'Full skill definitions for Boundaries and Form, Structure, and Sense', false),
  ('https://satsuite.collegeboard.org/sat/whats-on-the-test/structure', 4, 'Module length and timing', false),
  ('https://satsuite.collegeboard.org/practice/practice-tests', 5, 'Official full-length practice in Bluebook', false),
